INSERT INTO public.document_pages VALUES (13, 12, '2026-07-03', 1, 'Imported Page 1', '<p><strong>Rule – 15: Withdrawals from the Fund</strong></p><p><strong>(1) </strong>Subject to the conditions specified therein, withdrawals may be sanctioned by the</p><p>authorities competent to sanction an advance for special reasons under sub-rule (2) of Rule</p><p>12, at any time –</p><p><strong>(A) </strong>after the completion of (fifteen) years of service (including broken periods of service, if</p><p>any) of a subscriber or within then years before the date of his retirement on</p><p>superannuation, whichever is earlier, from the amount standing to his credit in the Fund,</p><p>for one or more of the following purposes, namely :-</p><p><strong>(a) </strong>meeting the cost of higher education, including where necessary, the traveling expenses of</p><p>the subscriber or any child of the subscriber in the following cases, namely:-</p><p>(i) for education outside India for academic, technical, professional or vocational course</p><p>beyond the High School stage; and</p><p>(ii) for any medical, engineering or other technical or specialized course in India beyond the</p><p>High School stage;</p><p><strong>(b) </strong>meeting the expenditure in connection with the betrothal/marriage of the subscriber or his</p><p>sons or his daughters, and any other female relation actually dependent on him;</p><p><strong>(c) </strong>meeting the expenses in connection with the illness, including where necessary, the</p><p>traveling expenses of the subscriber and members of his family or any person actually</p><p>dependent on him ;</p><p><strong>(d) </strong>meeting the cost of consumer durables such as TV, VCR/VCP, washing machines, cooking</p><p>range, geysers and computers.</p><p><strong>(B) </strong>during the service of a subscriber, from the amount standing to his credit in the Fund for</p><p>one or more of the following purposes, namely :-</p><p>(a) building or acquiring a suitable house or ready-built flat for his residence including the cost</p><p>of the site, or any payment towards allotment of a plot or flat by the Delhi Development</p><p>Authority, State Housing Board or a House Building Society;</p><p>(b) repaying an outstanding amount on account of loan expressly taken for building or acquiring</p><p>a suitable house or ready-built flat for his residence;</p><p>(c) purchasing a house-site for building a house thereon for his residence or repaying any</p><p>outstanding amount on account of loan expressly taken for this purpose;</p><p>(d) reconstructing or making additions or alterations to a house or a flat already owned or</p><p>acquired by a subscriber;</p><p>(e) renovating, additions or alterations or upkeep of the ancestral house or a house built with</p><p>the assistance or loan from Government;</p><p>(f) constructing a house on a site purchased under Clause (c);</p><p><strong>(C) </strong>within twelve months before the date of subscriber’s retirement on superannuation from</p><p>the amount standing to the credit in the Fund, without linking to any purpose.</p>', 'D:\Admin_Sharing\Estt. Volumes\GPF\GPF F-W Rule.docx', false, 1);
INSERT INTO public.document_pages VALUES (14, 13, '2026-07-03', 1, 'Imported Page 1', '<p>                                                                         <strong>Self-Declaration</strong></p><p>I ____________________________ with Account No _______________ working as ________________ at ________________________ would like to withdraw my GPF for the purpose of __________________________________ and I wish to utilise the amount for the same.</p><p>                                                                                                   Signature:                                                                                                       </p><p>                                                                              Employee Name:</p><p>                                                                              Account No:</p><p>                                                                              Designation:</p>', 'D:\Admin_Sharing\Estt. Volumes\GPF\Self declaration.docx', false, 1);
INSERT INTO public.document_pages VALUES (15, 14, '2026-07-03', 1, 'Imported Page 1', '<p>From</p><p>________________________________</p><p>________________________________</p><p>________________________________</p><p>To</p><p>The CDA</p><p>No. 1, Staff Road,</p><p>Secunderabad – 500 009.</p><p>Subject:	Transfer-In – Reporting / Assumption of Charge</p><p>Reference:	HQrs. Office letter No. </p><p>**  **  **</p><p>Respected Sir,</p><p>	In compliance with HQrs. Office letter cited above, the undersigned has reported for duty at _______________________________________  on ____________ (FN) and assumed the charge as AAO w.e.f  ______________________.</p><p>	This is for information please.</p><p>									Yours faithfully,</p><p>Place	: Secunderabad</p><p>Date	:						</p><p>							          	(				     )</p><p>From</p><p>________________________________</p><p>________________________________</p><p>________________________________</p><p>To</p><p>The CDA</p><p>No. 1, Staff Road,</p><p>Secunderabad – 500 009.</p><p>Subject:	Assumption of Charge as __________________</p><p>Reference:	HQrs. Office letter No. </p><p>	CDA Sec’bad Lr. No. </p><p>**  **  **</p><p>Respected Sir,</p><p>	In compliance with HQrs. Office letter cited above, the undersigned has  assumed the charge as  _____________________________w.e.f  ______________________.</p><p>	This is for information please.</p><p>									Yours faithfully,</p><p>Place	: Secunderabad</p><p>Date	:						</p><p>							          	(				     )</p>', 'D:\Admin_Sharing\Forms\Assumption of Charge.docx', false, 1);
INSERT INTO public.document_pages VALUES (16, 15, '2026-07-03', 1, 'Imported Page 1', '<p><strong>UNDERTAKING</strong></p><p>I, 		                            hereby undertake that, in the event of any erroneous promotion noticed at later stage, I will be liable to refund the differences of Pay and Allowances to the department.</p><p>							</p><p>							Signature:</p><p>Place:						Name:</p><p>Date:							Designation:</p><p>Account No.</p>', 'D:\Admin_Sharing\Forms\undertaking on erroneous promotion.docx', false, 1);
INSERT INTO public.document_pages VALUES (17, 16, '2026-07-03', 1, 'Imported Page 1', '<p><strong>छुट्टी यात्रा रियायत हेतु अग्रिम भुगतान संबंधी आवेदन पत्र</strong></p><p><strong>APPLICATION FORM FOR GRANT OF LTC ADVANCE</strong></p><table><tbody><tr><td><p>1.</p></td><td><p>कार्मिक का नाम/NAME OF THE GOVERNMENT SERVANT</p></td><td></td></tr><tr><td><p>2.</p></td><td><p>पदनाम/DESIGNATION</p></td><td></td></tr><tr><td><p>3.</p></td><td><p>केन्द्रीय सरकारी सेवा ग्रहण करने की तारीख</p><p>DATE OF ENTERING THE CENTRAL GOVERNMENT SERVICE</p></td><td></td></tr><tr><td><p>4.</p></td><td><p>वर्तमान वेतन + ग्रेड वेतन/ PRESENT PAY + GRADE PAY</p></td><td></td></tr><tr><td><p>5.</p></td><td><p>स्थायी अथवा अस्थायी/WHETHER PERMANENT OR TEMPORARY</p></td><td></td></tr><tr><td><p>6.</p></td><td><p>सेवा पुस्तिका में दर्ज गृह नगर/HOME TOWN AS RECORDED IN THE SERVICE BOOK</p></td><td></td></tr><tr><td><p>7.</p></td><td><p>क्या पत्नी/पति सेवारत है यदि हाँ तो क्या छुट्टी यात्रा रियायत सुविधा के हकदार हैं?/WHETHER WIFE/HUSBAND IS EMPLOYED AND IF SO WHETHER ENTITLED TO LTC.</p></td><td></td></tr><tr><td><p>8.</p></td><td><p>क्या गृह नगर यात्रा के लिए रियायत का उपयोग किया जाना है? यदि हाँ तो किस ब्लॉक वर्ष के लिए छुट्टी यात्रा रियायत का उपयोग करना है/WHETHER THE CONCESSION IS TO BE AVAILED FOR VISITING HOME TOWN, AND IF SO BLOCK FOR WHICH LTC IS TO AVAILED.</p></td><td></td></tr><tr><td><p>9</p></td><td><p>यदि रियायत सुविधा का उपयोग " भारत में किसी भी स्थान" के लिए प्रयोग किया जा रहा है तो उस स्थान का नाम/IF THE CONCESSION IS TO VISITS " ANY WHERE IN INDIA" THE PLACE TO BE VISITED.</p></td><td></td></tr><tr><td><p>10.</p></td><td><p>किस ब्लॉक वर्ष के लिए लिया जा रहा है/BLOCK FOR WHICH TO BE AVAILED.</p></td><td></td></tr></tbody></table><p>11.	उन व्यक्तियों के नाम जिनके द्वारा छुट्टी यात्रा रियायत का उपयोग किया जाना  है।</p><p>	PERSONS IN RESPECT OF WHOM LTC IS PROPOSED TO BE AVAILED.</p><table><tbody><tr><td><p>क्र.सं./ SL.NO.</p></td><td><p>नाम तथा आयु/NAME AND AGE</p></td><td><p>कार्मिक से संबंध/RELATIONSHIP</p></td></tr><tr><td></td><td></td><td></td></tr></tbody></table><p>12.	अग्रिम भुगतान की राशि/ AMOUNT OF ADVANCE REQUIRED	:~ ___________________________________________________</p><p>		</p><p>	मैं यह प्रमाणित करता हूँ उपर्युक्त दी गई जानकारी मेरी जानकारी के अनुसार सत्य तथा सही है। मैं वचन देता हूँ कि अग्रिम राशि प्राप्त होने के 10 दिनों के भीतर ही जावक यात्रा की टिकट दिखा दूंगा।</p><p>	I DECLARE THAT THE PARTICULARS FURNISHED ABOVE ARE TRUE AND CORRECT TO THE BEST O MY KNOWLEDGE. I UNDERTAKE TO PRODUCE THE TICKET FOR THE OUTWARD JOURNEY WITHIN TEN DAYS OF RECEIPT OF THE ADVANCE.</p><p>								हस्ताक्षर/Signature 		:</p><p>								नाम/Name			:</p><p>								पदनाम/Designation		: </p><p>	</p>', 'D:\Admin_Sharing\FORMS-Imp\Application_form_for_grant_of_LTC_Advance.docx', false, 1);
INSERT INTO public.document_pages VALUES (18, 17, '2026-07-03', 1, 'Imported Page 1', '<p>छुट्टी यात्रा रियायत हेतु दावा </p><p>CLAIM FOR LEAVE TRAVEL CONCESSION</p><table><tbody><tr><td><ol><li>वैयक्तिक ब्यौरा/ Personal Details</li></ol></td><td rowspan="6"><ol><li>छुट्टियों का ब्यौरा/ Leave Details</li><li>छुट्टी की अवधि </li></ol><p>से/from------- तक/to ---------</p><p>Leave Period</p><ol><li>प्राधिकार	: कार्यालय आदेश सं.</li></ol><p>Authority	: Office Order No.</p><p>         दिनाँक/Date :</p><p>  III) घोषित छुट्टी का स्टेशन/</p><p>       गृह नगर</p><p>       Declared Leave Station/</p><p>       Home town			</p><p>दावे की तारीख/ Claim Preferred on </p></td><td colspan="4"><ol><li>परिवार के सदस्यों का ब्यौरा जिनके लिए छुट्टी यात्रा रियायत का दावा किया गया</li></ol><p>            FAMILY DETAILS FOR WHOM LTC CLAIMED</p></td></tr><tr><td><ol><li>नाम/Name</li></ol></td><td><p>क्र.स.</p><p>SL.</p></td><td><p>नाम/NAME</p></td><td><p>आयु</p><p>AGE</p></td><td><p>संबंध</p><p>RELATIONSHIP</p></td></tr><tr><td><ol><li>पदनाम/ट्रैड/ Designation/Trade</li></ol></td><td rowspan="4"></td><td rowspan="4"></td><td rowspan="4"></td><td rowspan="4"></td></tr><tr><td><ol><li>व्यैक्तिक सं./टी. सं./ Personal No./T.No.</li></ol></td></tr><tr><td><ol><li>यूनिट/फॉर्मेशन/ Unit/Formation</li></ol></td></tr><tr><td><ol><li>मूल वेतन+ ग्रेड वेतन	</li></ol><p>Basic Pay +Grade pay</p></td></tr></tbody></table><ol><li>यात्रा का ब्यौरा/JOURNEY DETAILS</li></ol><table><tbody><tr><td colspan="3"><p>    प्रस्थान/DEPARTURE</p></td><td colspan="3"><p>आगमन/ARRIVAL</p></td><td rowspan="2"><p>दूरी कि.मी. में/DISTANCE IN K..M.</p></td><td rowspan="2"><p>यात्रा का साधन एवं श्रेणी/MODE OF TRAVEL &amp; CLASS OF ACCOMMODATION</p></td><td rowspan="2"><p>किराया प्रति व्यक्ति/ FARE PER PERSONS</p></td><td rowspan="2"><p>व्यक्तियों की संख्या/ </p><p>Persons @</p></td><td rowspan="2"><p>सीमित करने के उपरांत राशि यदि कोई है तो/ AMOUNT AFTER RESTRICTION IF ANY</p></td><td rowspan="2"><p>कुल दावे की राशि/</p><p>TOTAL AMOUNT CLAIMED</p></td><td rowspan="2"><p>टिकट सं./ TICKET NO.</p></td><td rowspan="2"><p>अभ्युक्तियाँ/ REMARKS</p></td></tr><tr><td><p>दिनाँक</p><p>DATE</p></td><td><p>समय</p><p>TIME</p></td><td><p>स्टेशन</p><p>STATION</p></td><td><p>दिनाँक</p><p>DATE</p></td><td><p>समय</p><p>TIME</p></td><td><p>स्टेशन</p><p>STATION</p></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>		        कुल/Total =</p><p>5. भुगतान का प्रकार/MODE OF PAYMENT</p><table><tbody><tr><td></td><td><p>दावे की कुल राशि/ Total Amount claimed ~</p><p>आहरित अग्रिम घटायें /Less advance drawn ~</p><p>शेष/वसूसी देय /Balance/recovery due~</p></td><td><p>भुगतान प्राप्त किया/Received Payment</p><p>रसीदी टिकट/Revenue Stamp</p></td></tr></tbody></table><p>नोट - दावेदार द्वारा पीछे दिया गया प्रमाण अवश्य भरा जाना चाहिए 	दावेदार के हस्ताक्षर/Signature of the Claimant	</p><p>        तथा नियंत्रण अधिकारी द्वारा दावा प्रतिहस्ताक्षरित होना चाहिए।/	नाम/Name 		......................................</p><p>           The certificates on the reverse must be completed by 	लेखा सं./Personal No.	 .....................................</p><p>       the claimant and the controlling Officer countersigning 	पदनाम/Designation 	......................................</p><p>       the claim.	यूनिट/Unit		.....................................</p><p>@... उपर्युक्त मद सं -3 में परिवार के सदस्यों के ब्यौरे की पुष्टि क्र.स. में दर्शाएं</p><p>        Here, indicate Sl. No. persons conforming to </p><p>       family details given in item 3 above		 </p><p>प्रमाणित किया जाता है कि :-</p><ol><li>मैंने स्वयं अथवा अपने परिवार सदस्यों के लिए ब्लॉक वर्ष            तथा            के लिए कोई अन्य छुट्टी यात्रा रियायत दावा प्रस्तुत नहीं किया है। </li></ol><p>I have not submitted any other claim for LTC for my family members in r/o block year 20.................................... and 20........................................</p><ol><li>मैं पहले ही स्वयं/मेरी पत्नी/ बच्चों सहित स्वय के संबंध में छुट्टी यात्रा रियायत के लिए यात्रा भत्ते की निकासी कर चुका हूँ। यह दावा स्वयं/मेरी पत्नी/ बच्चों सहित स्वयं के संबंध में है। यह दावा स्वयं/मेरी पत्नी/ बच्चों सहित स्वय के संबंध में है इनमें से किसी ने भी इससे पूर्व यात्रा नहीं की है।</li></ol><p>I have already drawn TA for LTC in r/o a journey performed by me/myself with children. This claim is in r/o the journey performed by my wife/myself with children. This claim in r/o the journey performed be my wife/myself with children none of whom traveled with the party on the earlier occasion.</p><ol><li>मेरे/मेरी पति/पत्नी सरकारी सेवा में कार्यरत नहीं है अथवा मेरे/मेरी पति/पत्नी सरकारी सेवा में कार्यरत है तथा उनके द्वारा संबंधित ब्लॉक वर्ष में स्वयं या परिवार के किसी अन्य सदस्य के लिए अलग से रियायत सुविधा का प्रयोग नहीं किया गया है।</li></ol><p>That my husband/wife in not employed in Govt. Service or that my husband/wife is employed in Govt. Service and the concession has not been availed by him/her separately for himself/herself or any of the family members for the concerned block. </p><ol><li>यात्रा मेरे/मेरी पत्नी द्वारा बच्चों सहित घोषित गृह नगर/भारत में किसी भी स्थान पर की गई ।</li></ol><p>The journey has been performed by me/my wife with children to the declared hometown/any place in India viz................................... </p><ol><li>परिवार के जिन सदस्यों के संबंध में राशि के लिए  दावा किया गया वे यात्रा के प्रारंभ होने तक पूर्णतः मेरे ऊपर आश्रित थे तथा वास्तविक रुप से मेरे साथ रहते थे।</li></ol><p>That the family members in r/o whose journey the amount has been claimed were entirely dependent and actually residing with me at the time the journey was undertaken.</p><ol><li>यात्रा मेरे प्रमाणित गृह नगर/भारत में किसी भी से उस श्रेणी में वास्तविक रुप में की गई जिसके लिए दावा किया गया है।</li></ol><p>That the journey was actually performed to and from my certified Home/any place in India by the class of accommodation for which has been claimed. </p><ol><li>प्रमाणित किया जाता है कि  बिल में दावे के लिए प्रस्तुत राशि सबसे छोटे रुट की है।</li></ol><p>Certified that the fare claimed in this bill are by the shortest route. </p><ol><li>प्रमाणित किया जाता है कि यात्रा मेल/एक्सप्रेस रेलों द्वारा की गई है।</li></ol><p>Certified that the journey was performed by the Mail/Express trains.</p><ol><li>प्रमाणित किया जाता है कि विद्यार्थी रियायत का उपभोग किया गया/नहीं किया गया है।</li></ol><p>Certified that the students'' concession has been availed/has not been availed.</p><p>		सरकारी कर्मचारी के हस्ताक्षर/Signature of the Govt. Servant</p><p>		दिनाँक/Date</p><p><strong>नियंत्रण प्राधिकारी द्वारा प्रमाणित किया जाए/Certified by the Controlling Authority</strong></p><ol><li>कि यात्रा सरकारी कर्मचारी द्वारा की गई यात्रा उसकी सेवा पुस्तिका में दर्ज गृहनगर से की गई थी।</li><li>That the journeys were performed actually to the declared home of the Govt. servant as recorded in his service book/any place in India viz....... </li><li>जिस टिकट पर अग्रिम का उपयोग किया गया है वह सरकारी कर्मचारी द्वारा प्रस्तुत की गई है तथा इसकी संख्या, तारीख एवं राशि नोट कर ली गई है।</li><li>That the tickets for the journey has been produced by the Govt. Servant and the numbers date and amount has been noted where the advance has been availed.</li><li>कैलेंडर वर्ष के चालू ब्लॉक में छूट का उपभोग एक बार से अधिक नहीं किया गया है।</li><li>That the concession was not availed of more than once in current block of the calendar year.</li><li>कि श्री ............................................ द्वारा नियमित/आकस्मिक छुट्टी पर यात्रा की गई।</li><li>That the journey have been performed by Shri............................................ during regular/casual leave.</li><li>कि श्री....................................... ने जावक यात्रा प्रारंभ करने की तारीख से  एक वर्ष या अधिक समय तक लगातार सेवा की है।</li><li>That Shri...................................................................... has rendered continuous service for one year or more on the date of commencement of outward journey.</li><li>नियम के अधीन अपेक्षित आवश्यक प्रविष्टयाँ श्री ..................................................  की सेवा पुस्तिका में कर दी गई हैं। सेवा पुस्तिका/अभिलेख के अनुसार व्यक्ति द्वारा बताए गए आश्रित वास्तव में उस पर आश्रित हैं। </li><li>That the necessary entries as required under Rule have been made in the service book of Shri........................................................... dependents shown by the individual are actually depend upon him/her as per service book/records.</li><li>प्रमाणित किया जाता है कि उक्त दावे को पूर्व में प्रस्तुत नहीं किया गया और न भुगतान किया गया।</li><li>Certified that the claim has not been preferred and paid earlier.</li></ol><p>जाँच की तथा निम्नानुसार भुगतान हेतु ~.......................... (~.........................................................................) के लिए पास किया।</p><p>Checked and passed for ~............................................. (~.....................................................................................................................) for payment as under</p><table><tbody><tr><td><p>खजाना/Treasury</p></td><td><p>आदाता/Payee</p></td><td><p>राशि/Amount</p></td><td><p>डी.वी.सं./D.V. No.</p></td><td><p>चेक सं तथा दिनाँक/Cheque No. &amp; Date</p></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>लेखापरीक्षक/Auditor	अनुभाग अधिकारी (ए)/ स.ले.अ./SO (A)/AAO				ले.अ./AO		</p>', 'D:\Admin_Sharing\FORMS-Imp\Claim_for_LTC.docx', false, 1);
INSERT INTO public.document_pages VALUES (19, 18, '2026-07-03', 1, 'Imported Page 1', '<p>अस्थायी कार्य (दौरे) पर जाने हेतु दावे के संबंध में</p><p>CLAIM FOR MOVE ON TEMPORARY DUTY (TOUR)</p><p>दावेदार का नाम, रैंक तथा यूनिट	  :</p><p>Name, rank and unit of claimant: </p><p>कार्यालय/office:						मूल वेतन + ग्रेड वेतन : ~</p><p>	   						Basic Pay + Grade Pay: ~</p><p>संचलन के आदेश : का.आ.स.			दिनाँक:		प्राधिकार (यात्रा विनियमावली./पूरक नियमावली के नियम)</p><p>Orders for move: O.O. NO.			Date:		Authority (Rule in TR/SR): SR</p><p>स्थान जहाँ से यात्रा आरंभ की गई 				प्रारंभ की तिथि/समय:	      	(क)	      समय</p><p>Station from which journey commenced 			Date/Time of start:		 (a)	      hrs.</p><p>सड़क, रेल, वायु, स्टीमर आदि मार्ग से यात्रा का ब्यौरा तथा यात्रा/पड़ाव हेतु महंगाई भत्ता</p><p>Details of journey by Road, Rail, Air, Steamer, etc. and DA for journey/halt</p><table><tbody><tr><td><p>पहँचने के स्थान का नाम/  Name of the place arrived at</p></td><td colspan="2"><p>आगमन/Arrival</p><p>दिनाँक         समय                 	  (क)</p><p>Date         Hours                                 	(a)</p></td><td><p>दूरी सड़क मार्ग से/ Distance by road in Km</p></td><td colspan="2"><p>सवारी का साधन/श्रेणी/</p><p>Conveyance Mode/Class</p></td><td colspan="2"><p>प्रस्थान/Departure</p><p>दिनाँक           बजे </p><p>Date                 Hours                   </p></td><td><p>म.भ. की सं. (सी)/ No. of DA (c)</p></td><td colspan="2"><p>सड़क मील भत्ता/महंगाई भत्ते की दर/ Rate of RMA/DA</p></td><td><p>रु./Rs.</p></td><td><p>पै./P</p></td><td><p>अभ्युक्तियाँ/</p><p>(घ)</p><p>Remarks</p><p>(d)</p></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td colspan="2"></td><td></td><td></td><td></td><td colspan="2"><p>कुल/Total</p></td><td></td><td></td><td></td></tr><tr><td colspan="5"><p>चैक स्वयं/बैंकर आदि के पक्ष में जारी किया जाए/</p><p>Cheque to be issued in favour of self/bankers etc.</p><p>~</p></td><td colspan="5"><p>कुल /Total: ~</p><p>अग्रिम राशि :</p><p>Amount of advance</p><p>शेष/Balance: ~</p></td><td colspan="4"><p>भुगतान प्राप्त किया</p><p>Received Payment</p></td></tr></tbody></table><p> </p><p>रेल/वायुयान/बस का नियत समय दर्शाएं</p><p>Indicate schedule Train/Air/Bus timing</p><p>प्रमाणित किया जाता है कि /Certified that</p><p>1.	मैंने दावे में दी गई मार्ग की दूरी के लिए सरकारी वाहन का प्रयोग नहीं किया था।</p><p>	I did not use Government transport for which road mileage allowance has been claimed.</p><p>2.	प्रस्तुत बिल दर्शाई गई यात्रा के किसी भी हिस्से के लिए मैंने रेलवे वारंट रियायत वाउचरों का प्रयोग नहीं किया 	था।</p><p>	I did not use railway warrant concession vouchers for any portion of journey for which bills 	preferred.</p><p>3.	मुझे किसी भी प्रकार की मुफ्त भोजन और रहने के स्थान की सुविधा प्रदान नहीं की गई थी।</p><p>	I was not provided with free boarding or lodging facilities. </p><p>4.	जिन दिनों के लिए दैनिक भत्तों का दावा किया गया है मैं बाह्य स्थान पर प्रलक्षित रुप में ही नहीं बल्कि वास्तविक रुप में 	मौजुद था और मैं आकस्मिक छुट्टी या किसी अन्य प्रकार की छुट्टी पर नहीं गया।</p><p>I was actually and not merely constructively present at the outstation on the days on which DA has been claimed and I did not proceed on CL or any other leave during the period.</p><p>5.	मैं पहले कभी इस प्रकार के किसी पाठ्यक्रम/परीक्षा में शामिल नहीं हुआ था। </p><p>	I had not attended a previous similar course/examination. 	 </p><p>स्थान/Station</p><p>दिनाँक/Date </p><p>सही दावे के लिए प्रतिहस्ताक्षर</p><p>Countersigned as correct claim</p><p>                                                                                                </p><p> यात्रा करने वाले अधिकारी के हस्ताक्षर</p><p>								                 Signature of the officer traveling </p><p>दावे को प्रतिहस्ताक्षरित करने वाले अधिकारी के हस्ताक्षर तथा पदनाम</p><p>Signature and designation of the Officer countersigning the claim</p><p>भुगतान हेतु पास किया/Passed for payment _________________________________________________________</p><p>के पक्ष में/In favour of __________________________________________________________________________ </p><p> </p><p>खजाना/Treasury					आदाता/Payee				राशि/Amount</p><p>(लेखापरीक्षक)/Auditor			   स.ले.अ.(प्रशा.)/AAO (AN)			वरि.ले.अ. (लेप.)Sr. AO (AT)</p>', 'D:\Admin_Sharing\FORMS-Imp\Claim_for_move_on_Temorary_Duty_(Tour).docx', false, 1);
INSERT INTO public.document_pages VALUES (20, 19, '2026-07-03', 1, 'Imported Page 1', '<table><tbody><tr><td><p><strong>Sr. No</strong></p></td><td><p><strong>Pending Issues</strong></p></td><td><p><strong>Comments of IT&amp;SDC</strong></p></td><td><p><strong>PDC</strong></p></td><td><p><strong>Current Status</strong></p></td></tr><tr><td><p>1</p></td><td><p>Systemic changes in the department: issues related Tulip system raised by PCDA (Army) Pune “Tracing the activity of allot and re-allot of 3<sup>rd</sup> party bills.”</p></td><td><p>Can be Developed</p></td><td><p>30.05.25</p></td><td></td></tr><tr><td><p>2</p></td><td><p>Provide query to extract data from Tulip database for “Analysis of data of last one year through Tulip with regard to time taken to release payments by units after obtaining Cash Assignments in respect of PCDA New Delhi, CDA (Army) Delhi Cantt, PCDA (Army) Chandigarh, vis-à-vis payments by the concerned PCsDA/CsDA” An Standard format on Tulip is to be developed for future reports.”</p></td><td><p>SQL  Query has been sent.</p></td><td><p>-</p></td><td></td></tr><tr><td><p>3</p></td><td><p>Information with respect to vendor invoice no. and date are also to be shared with vendors through Tulip.</p></td><td><p>Already done. Updated information to HQ IT Wing. Once CGDA approves, code will be made live.</p></td><td><p>-</p></td><td></td></tr><tr><td><p>4</p></td><td><p>Status of project Tulip 2.0 </p></td><td><p>Already sent over email to HQ office on 07.05.2025</p></td><td><p>-</p></td><td></td></tr><tr><td><p>5</p></td><td><p>Entry of vendor details, viz., Type of industry (MSME / PSU / others etc.) in Tulip may be made compulsory.</p></td><td><p>This feature is already available in Tulip</p></td><td><p>-</p></td><td></td></tr><tr><td><p>6</p></td><td><p>Institutionalizing of internal audit mechanism for CCS programme executed under ADA.</p></td><td><p>Testing underway</p></td><td><p>-</p></td><td></td></tr><tr><td><p>7</p></td><td><p>Additional integration for sharing sanction &amp; supply order document after contract placement on GeM.</p></td><td><p>Not yet started</p></td><td><p>Will assess and get back</p></td><td></td></tr><tr><td><p>8</p></td><td><p>Accounting modalities likely to be followed for Unified Pension Scheme(UPS) and draft amendment to Pamphlet of RDR Heads(2020 RPT</p></td><td><p>Under Progress</p></td><td><p>15.05.25</p></td><td></td></tr><tr><td><p>9</p></td><td><p>API Integration: NIDHI 2.0</p></td><td><p>Original PDC was 25.04.2025. As of now, Design is changed at NIDHI side for having two APIs now. Revised Coding done. UAT is underway.</p></td><td></td><td></td></tr><tr><td><p>10</p></td><td><p>OTP for biometric based login</p></td><td><p>Under Progress</p></td><td rowspan="4"><p>30 working days i.e. 24.06.25</p></td><td></td></tr><tr><td><p>11</p></td><td><p>Screen logout after an appropriate time</p></td><td><p>Under Progress</p></td><td></td></tr><tr><td><p>12</p></td><td><p>Online auditing system for transactions in Dolphin</p></td><td><p>Under Progress</p></td><td></td></tr><tr><td><p>13</p></td><td><p>Maintaining audit trails which can establish digital footprints of user login, access duration of each functionary.</p></td><td><p>Under Progress</p></td><td></td></tr><tr><td><p>14</p></td><td><p>Identification of expenditure in r/o all the allowances under Def. Service Estimates. (emailed on 24.03.2025 &amp; 03.04.2025)</p></td><td colspan="2"><p>Comments of  IT&amp;SDC, Secunderabad has not yet been received</p></td><td></td></tr></tbody></table><p><strong>OFFICE NOTE</strong></p><p>						 No: IT-Corr0598/2/2020-IT</p><p>							           Dated:       /05/2025</p><p>Sub: Implementation of Project Automation of Claim.</p><p>PUC is the letter No. Air HQ/25751/TA DA/D Accts/CS dated 30.04.2025 received from Air HQ regarding the present status of the implementation of Project Automation of Claims in the Indian Air Force.</p><p>2.	The matter was earlier received vide Air HQ letter No. Air HQ/25751/TA DA/D Accts/CS dated 26.02.2025 which pertained to audit wing. Accordingly, as directed by competent authority, the subject file was marked to Audit-IV wing for necessary action. The subject file is currently held with Audit-IV wing. Copies of the relevant correspondence are placed opposite for ready reference. </p><p>3.	Now, Air HQ has sought the present status of the case. As the file is presently with Audit-IV wing, it is proposed that the same may be forwarded to Audit-IV wing for furnishing the current status to Air HQ. Draft for approval is placed opposite.</p><p>Submitted for orders, please.</p><p>Sunil Kumar</p><p>AAO (IT&amp;S)</p><p>Sr. AO (IT&amp;S)</p><p><strong>Office Note</strong></p><p>  </p><p>No. No: IT-7080/TULIP /1/2023-IT</p><p>							Dated:       /05/2025</p><p><strong>Sub : Upgradation of Area Accounts Office Kolkata</strong></p><p>PUC is UO NO. AT-Corrd/13108/CDA(EC) Kolkata dated 07.05.2025 received from AT-Corrd (local) for examination and comments of this wing regarding upgradation of Area Accounts Office Kolkata.</p><p>2.	A Copy of DO letter dated 10.03.2025 from Lt.Gen Ulhas Kirpekar, ABSM, SM, DGFP Delhi is enclosed with AT-Corrd letter mentioned above. In this DO, the long pending issue of upgradation of existing Area Account Office, Kolkata to PCDA Kolkata has been raised. It has further been highlighted that currently only offline bills are being processed by AAO Kolkata. The office does not have an ‘E’ Sec, GeM Sec and access to update payment bills of formation/units under its jurisdiction. As an interim measure, empowerment of AAO Kolkata with access to updated payment in TULIP Software System, ‘E’ Sec and GeM Sec, has been proposed.</p><p>3.	In this regards, it is submitted that the matter pertains to policy decisions and falls within the purview of the Domain wing i.e. Audit Wing. If any new functionality in Tulip is to be required, Audit wing may be requested to furnish the details of the required functionalities for further necessary action. Draft UO is placed opposite for approval.</p><p>Submitted for orders, please.</p><p>Sunil Kumar</p><p>AAO (IT&amp;S)</p><p>Sr. AO (IT&amp;S)</p><p><strong>OFFICE NOTE</strong></p><p>						 No: IT-7080/TULIP /1/2023-IT</p><p>							      Dated:       /05/2025</p><p>Sub: Various Utility to be develop in Tulip : SOM Directions</p><p>PUC is MoM of SOM held on 14.05.2025.</p><p>2.	With reference to point number 2 (vi) &amp; 2 (ix) of the minutes of meeting of SOM held on 14.05.2025, wherein directions for incorporating following points into Tulip system were issued. </p><table><tbody><tr><td><p><strong>Point No.</strong></p></td><td><p><strong>Actionable Points</strong></p></td><td><p><strong>IT&amp;S wing comments</strong></p></td></tr><tr><td><p>2(vi)</p></td><td><p>Reasons of rejection of Bills for other than GeM bills to be included in Tulip</p></td><td><p>To explore the feasibility of the above, a mail dated 16.05.2025 was sent to IT&amp;SDC Secunderabad, seeking their comments. In response, IT&amp;SDC Secunderabad intimated that currently concerned section can create custom rejection reasons. However, if rejection reason for non-GeM bills are standardized, the same will be incorporated in Tulip.</p></td></tr><tr><td><p>2 (ix)</p></td><td><ol><li>Letter to be issued to all PCDA/CDA and Service HQrs to mandatorily enter the following vendor’s details (but not limited to) in the bills:</li><li>Email id of the vendor</li><li>Mobile No. of vendor</li><li>Nature of vendor Viz. MSME/PSU/Others Etc.</li></ol><p>(b) Requirement regarding the same to be obtained by Audit IX form IT&amp;S Wing before issuing of the letter. </p></td><td><p>As informed by IT&amp;SDC Secunderabad, Utility for entering the vendor’s details will be developed by 31.05.2025. Meanwhile requirement for this functionalities may be obtained by Audit IX as directed.  </p></td></tr></tbody></table><p>3.	In view of the above, if agreed to, following is proposed:</p><ul><li><ol><li>A standardized list of rejections reasons for non-GeM bills may be obtained from Audit wing for incorporation in Tulip system. </li><li>Requirement for this functionalities mentioned at point 2 may be obtained by Audit IX. </li></ol></li></ul><p>Draft UO to Audit wing is placed opposite for approval. </p><p>&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp; Submitted for orders please.	</p><p>								(Sunil Kumar)</p><p>										AAO(IT&amp;S)</p><p>Sr. AO(IT&amp;S)</p><p><strong>OFFICE NOTE</strong></p><p>						 No: IT-7080/TULIP /1/2023-IT</p><p>							        Dated:       /05/2025</p><p>Subject: Handover of Project FALCON Source Code and its maintenance.</p><p>PUC is CDA (IT&amp;SDC) Secunderabad letter No. IT&amp;SDC/SysMisc/Falcon/1/25 dated 06.05.2025 wherein proposal regarding handing over of Project FALCON Source code and its maintenance is received.</p><p>2.	IT&amp;SDC, Secunderabad vide their letter mentioned above, informed that Project FALCON was developed by ITSDC using SpringBoot and React, covering the entire area of work related to Pay and Allowances of Army Officers by PCDA(O), Pune, went live in January 2024.</p><p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Since the launch, the initial phase experienced several issues which were progressively addressed. Following HQrs inspection of PCDA(O) Pune in Jan 2025, a list of 25 critical pending issues was identified. As per the review chaired by Shri R.K. Arora, IDAS, Special CGDA on 09/04/2025, only one issue remained unresolved as on 14/04/2025. This too was resolved via a software update on 15/04/2025. At present, there are no outstanding issues with ITSDC, Secunderabad.</p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;It is also added that over the past 15 months, ITSDC and PCDA(O), with continuous support from Hqrs have collaboratively stabilized the Project. During this period, a dedicated team of two programmers and system administrators was constituted by PCDA(O) and trained by ITSDC in areas such as system design, architecture and source code maintenance. For the past 6 months, the closing processes have been carried out independently by PCDA(O), indicating their readiness to take over the system.</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;In this regards it is submitted that ensuring the security and version control of Project FALCON is essential to minimize the risk of uncoordinated or unauthorized modifications, thereby maintaining system auditability, consistency and data integrity. </p><p>a) 	Furthermore, it is observed that most of the day-to-day queries raised through the Samanvay Portal are of a routine nature and can be managed by the PCDA (O) Pune. </p><p>6. In view of the above, following is proposed:</p><ul><li><ol><li>The source code of Project FALCON may be retained securely at ITSDC, Secunderabad to ensure its integrity and security.</li><li>Two officers from PCDA(O), Pune may be provided additional training by ITSDC specifically for handling day-to-day user issues raised through the Samanvay Portal. This will ensure sustained technical capability at PCDA(O) and timely resolution of operational issues </li></ol></li></ul><p>Draft letter is placed opposite for approval</p><p>Submitted for orders, please</p><p>                  Auditor (IT&amp;S)</p><p>      <br></p><p><strong>OFFICE NOTE</strong></p><p>						 No: IT-7080/TULIP /1/2023-IT</p><p>							        Dated:       /05/2025</p><p>Subject: Migration of OAP modules for Naval Personnel Claims to TULIP-Reg.</p><p>PUC is DO letter No IT&amp;S/036/TULIP-OAP/Corr dated 15.05.2025 from Shri Harsh Vaidya, IDAS, PCDA (Navy) Mumbai regarding the above mentioned subject.</p><ol><li>In this DO, it has been highlighted that PCDA (Navy) Mumbai is currently processing the personnel claims of Naval staff using the legacy OAP system developed in Visual FoxPro (VFP) in 2000 which has not been supported since 2016. The system is facing increasing technical failures, compatibility issues with modern platforms and delays in claim processing, leading to user dissatisfaction and operational risk.</li><li>The requirement to migrate the OAP modules, especially TADA to the TULIP platform was also brought up during the CGDA’s inspection of PCDA (Navy) in December 2023. PCDA (Navy) has sought prompt intervention to initiate this migration to ensure continuity and efficiency in claims processing. </li><li>In this regard, it is submitted that upgradation of TULIP application (TULIP 2.0) is underway. As per the enclosed report, IT&amp;SDC has examined the feasibility of inclusion of these modules into TULIP 2.0. </li><li>In view of the above, if agreed to we may be requested to CDA, IT&amp;SDC Secunderabad to take necessary action to expedite the integration of these modules into TULIP 2.0 on a priority basis. The same may be communicated to PCDA (Navy) Mumbai. DFAs is placed opposite for approval. </li></ol><p>Submitted for orders please</p><p>Sunil Kumar</p><p>AAO (IT&amp;S)</p><p>Sr. AO (IT&amp;S)</p>', 'D:\Admin_Sharing\ITSDC Pending issues (1).docx', false, 1);
INSERT INTO public.document_pages VALUES (21, 20, '2026-07-03', 1, 'Imported Page 1', '<p><strong>Basic Python Course – 20 sessions (5 days)</strong></p><table><tbody><tr><td><p><strong>Session</strong></p></td><td><p><strong>Topic</strong></p></td></tr><tr><td><p>1</p></td><td><p>Introduction to Python</p><p>Jupyter IDE<br>Variables</p><p>Data Types</p><p>Comments</p></td></tr><tr><td><p>2-3</p></td><td><p>Operators</p><p>Strings</p><p>Date and Time</p></td></tr><tr><td><p>4-5</p></td><td><p>Lists</p><p>Sorting lists</p><p>List comprehensions</p></td></tr><tr><td><p>6</p></td><td><p>Tuples</p><p>Sets</p><p>Dictionaries</p></td></tr><tr><td><p>7-8</p></td><td><p>Control Flow</p><p>If .. else</p><p>while</p><p>for loops</p></td></tr><tr><td><p>9-10</p></td><td><p>Functions</p><p>Default parameters</p><p>Positional arguments</p><p>Keyword arguments</p></td></tr><tr><td><p>11-12</p></td><td><p>Classes</p><p>Inheritance</p><p>Generators</p></td></tr><tr><td><p>13</p></td><td><p>Modules</p><p>Packages</p></td></tr><tr><td><p>14-15</p></td><td><p>File Handling</p></td></tr><tr><td><p>16</p></td><td><p>Exception Handling</p></td></tr><tr><td><p>17</p></td><td><p>Logging</p><p>Output formatting</p></td></tr><tr><td><p>18</p></td><td><p>Virtual Environments</p></td></tr><tr><td><p>19-20</p></td><td><p>Testing - Pytest</p></td></tr></tbody></table><p><strong>Python Data Analysis using Pandas – 20 Sessions (5 days)</strong></p><p>(After the Basic Python Course)</p><table><tbody><tr><td><p><strong>Session</strong></p></td><td><p><strong>Topic</strong></p></td></tr><tr><td><p>1-4</p></td><td><p>Structured Query language using PostgreSQL</p><p>Data Definition Language</p><p>INSERT, SELECT, UPDATE, DELETE</p><p>Aggregate Functions</p><p>JOINs</p></td></tr><tr><td><p>3</p></td><td><p>Pandas</p><p>Data structures</p></td></tr><tr><td><p>4-7</p></td><td><p>Pandas Dataframe</p><p>Indexing</p><p>Selection</p><p>Filtering</p><p>Sorting</p></td></tr><tr><td><p>8</p></td><td><p>Pandas Data Cleaning</p><p>Empty cells</p><p>Duplicates</p><p>Wrong format</p><p>Wrong data </p></td></tr><tr><td><p>9-10</p></td><td><p>Pandas</p><p>Data loading and storing – files and databases</p><p>CSV, Excel, JSON</p></td></tr><tr><td><p>11-12</p></td><td><p>Pandas</p><p>Combining and merging datasets</p></td></tr><tr><td><p>13-14</p></td><td><p>Pandas</p><p>Reshaping data – pivoting</p></td></tr><tr><td><p>15-17</p></td><td><p>Data Visualisation</p><p>Matplotlib -plotting, markers, labels, grid</p><p>Line, Bar, Scatter, Histogram, Pie charts</p><p>Subplots</p></td></tr><tr><td><p>18</p></td><td><p>Data Visualisation</p><p>Pandas and Seaborn</p></td></tr><tr><td><p>19-20</p></td><td><p>Pandas</p><p>Data Aggregation</p></td></tr></tbody></table><p><strong>Basic Java – 20 Sessions (5 days)</strong></p><table><tbody><tr><td><p><strong>Session</strong></p></td><td><p><strong>Topic</strong></p></td></tr><tr><td><p>1</p></td><td><p>Introduction to Java</p><p>Eclipse IDE</p><p>Variables</p><p>Data Types</p><p>Comments</p></td></tr><tr><td><p>2-3</p></td><td><p>Operators</p><p>Strings</p><p>Dates</p></td></tr><tr><td><p>4-5</p></td><td><p>Flow Control</p><p>if .. else</p><p>switch</p><p>while and for loops</p><p>break and continue</p></td></tr><tr><td><p>6-7</p></td><td><p>Java methods</p><p>Method parameters</p><p>Method overloading</p></td></tr><tr><td><p>8-11</p></td><td><p>Object Oriented Programming</p><p>Classes – attributes and methods</p><p>Access modifiers – public, private, protected, default</p><p>Non-access modifiers – final, abstract, static</p></td></tr><tr><td><p>12-13</p></td><td><p>Classes</p><p>Inheritance</p><p>Polymorphism</p><p>Interface</p><p>Packages</p></td></tr><tr><td><p>14-15</p></td><td><p>Data Structures</p><p>ArrayList</p><p>HashMap</p><p>HashSet</p></td></tr><tr><td><p>16-18</p></td><td><p>File Handling</p><p>Read and Write files</p><p>Exception Handling</p></td></tr><tr><td><p>19-20</p></td><td><p>Introduction to testing - JUnit</p></td></tr></tbody></table><p><strong>Java Spring Boot – 20 Sessions (5 days)</strong></p><p>(After Basic Java Course)</p><table><tbody><tr><td><p><strong>Session</strong></p></td><td><p><strong>Topic</strong></p></td></tr><tr><td><p>1-2</p></td><td><p>Spring Tool Suite IDE</p><p>Spring Initializer</p><p>Maven – Project Management Tool</p></td></tr><tr><td><p>3-4</p></td><td><p>Starter Packages</p><p>REST API</p><p>@GetMapping</p><p>@PostMapping</p><p>@PutMapping</p><p>@DeleteMapping</p><p>@PatchMapping</p></td></tr><tr><td><p>5</p></td><td><p>Introduction to Structured Query Language</p><p>INSERT, SELECT, UPDATE, DELETE</p><p>JOINs</p></td></tr><tr><td><p>6-8</p></td><td><p>Database Access - PostgreSQL</p><p>JPA</p><p>Repository Interface</p></td></tr><tr><td><p>9-12</p></td><td><p>Template Engines</p><p>Thymeleaf</p></td></tr><tr><td><p>13-14</p></td><td><p>Configuration and Monitoring</p><p>Configuration Properties</p><p>Actuator</p><p>Logging</p></td></tr><tr><td><p>15-17</p></td><td><p>Spring Security</p><p>Authentication</p><p>Access Control</p><p>CORS (Cross Origin Resource Sharing)</p><p>CSRF (Cross  Site Request Forgery)</p></td></tr><tr><td><p>18-19</p></td><td><p>Testing</p><p>Unit Testing - JUnit</p><p>Integration Testing – SpringBootTest</p></td></tr><tr><td><p>20</p></td><td><p>Deployment</p><p>Executable jar</p></td></tr></tbody></table>', 'D:\Admin_Sharing\KVN_PC_Backup\Downloads\Training\Pyhton_and_Java_Courses.docx', false, 1);
INSERT INTO public.document_pages VALUES (22, 21, '2026-07-03', 1, 'Imported Page 1', '<table><tbody><tr><td><p><strong>Sl.No.</strong></p></td><td><p><strong>Items Description</strong></p></td><td><p><strong>Description</strong></p></td><td><p><strong>PARAMETER</strong></p></td></tr><tr><td><p>1</p></td><td><p>Processor type</p></td><td><p>Intel core ultra 7- 155H or higher H series processors </p></td><td><p>Essential</p></td></tr><tr><td><p>2</p></td><td><p>Chipset</p></td><td><p>Intel® Integrated SoC</p></td><td><p>Essential</p></td></tr><tr><td><p>3</p></td><td><p>RAM memory</p></td><td><p>32 GB (16GB*2) DDR5-5600 Mhz  DIMM memory (2 DIMMs, Dual Channel) or higher</p></td><td><p>Essential</p></td></tr><tr><td><p>4</p></td><td><p>Internal Storage</p></td><td><p>1 TB PCIe-4x4 NVMe TLC SSD (Gen4)</p></td><td><p>Essential</p></td></tr><tr><td><p>5</p></td><td><p>Display</p></td><td><p>16.0" diagonal Anti-Glare WUXGA (1920x1200) UWVA IPS WLED display, Low Power, Low Blue Light, 400 nits brightness</p></td><td><p>Essential</p></td></tr><tr><td rowspan="2"><p>6</p></td><td rowspan="2"><p>Interface/ports</p></td><td><p>1. Two Thunderbolt™ 4 with USB Type-C; <br>2. Two Super Speed  3.2 Gen 1.0 or higher USB Type-A 5Gbps signaling rate ; <br>3. One HDMI 2.1<br>4. RJ45 Ethernet Port<br>5.Headphone/mic combo jack , Security Lock slot</p></td><td><p>Essential</p></td></tr><tr><td><p>6. Keyboard with numeric keypad, spill-resistant, Durakey keyboard, Backlit - Clickpad with multi-touch gesture support</p></td><td><p>Essential</p></td></tr><tr><td><p>7</p></td><td><p>Audio</p></td><td><p>Integrated stereo speakers, integrated microphone.</p></td><td><p>Essential</p></td></tr><tr><td><p>8</p></td><td><p>Integrated Camera</p></td><td><p>Integrated 5MP IR webcam with wide field of view and dual-microphone array</p></td><td><p>Essential</p></td></tr><tr><td rowspan="2"><p>9</p></td><td rowspan="2"><p>Communication</p></td><td><p>Integrated 10/100/1000 Gigabit Ethernet port </p></td><td><p>Essential</p></td></tr><tr><td><p>Intel AX211 Wi-Fi 6E 160 MHz +Bluetooth 5.3</p></td><td><p>Essential</p></td></tr><tr><td><p>10</p></td><td><p>Power</p></td><td><p>Smart 65 W External AC USB Type-C® power adapter</p></td><td><p>Essential</p></td></tr><tr><td><p>11</p></td><td><p>Battery Type</p></td><td><p>Long Life 3-cell, 56 Wh Li-ion polymer or higher</p></td><td><p>Essential</p></td></tr><tr><td><p>12</p></td><td><p>Accessories</p></td><td><p>Battery, AC power Adaptor Cables etc. from same OEM make.</p></td><td><p>Essential</p></td></tr><tr><td><p>13</p></td><td><p>Operating System</p></td><td><p>DOS</p></td><td><p>Essential</p></td></tr><tr><td><p>14</p></td><td><p>Laptop bag</p></td><td><p>laptop bag to be supplied.</p></td><td><p>Essential</p></td></tr><tr><td><p>15</p></td><td><p>Wireless Mouse</p></td><td><p>OEM''s Wireless mouse has to be supplied</p></td><td><p>&nbsp;</p></td></tr><tr><td><p>16</p></td><td><p>warranty</p></td><td><p>Three (3) year comprehensive on-site warranty from the date of installation &amp; acceptance (including  Harddisk retention policy from OEM and faulty harddrive will not be returned)</p></td><td><p>Essential</p></td></tr><tr><td rowspan="2"><p>17</p></td><td colspan="2"><p>Terms and conditions</p></td><td><p>&nbsp;</p></td></tr><tr><td colspan="2"><p>Bidder''s offer is liable to be rejected if they don''t upload any of the certificates / documents  with validity sought in the Bid and Corrigendum if any.</p></td><td><p>Essential</p></td></tr><tr><td rowspan="6"><p>18</p></td><td colspan="2"><p>Following Certifications to be submitted along with technical bid:</p></td><td><p>&nbsp;</p></td></tr><tr><td colspan="2"><p><br>a) OEM  should have Energy Star, MIL STD passing 18 Test, BEE latest certification for the quoted item.</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>b) OEM  should have EPEAT Gold India  or ROHS  or  EPR latest certification for the quoted item</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>d) OEM  should have ISO 9001 &amp; 14001 certified unit (Proof of certification required to be submitted)</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>e) OEM should enclose their compliance to the Land border sharing as per Govt. order.</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>f) OEM headquarters should not be in China</p></td><td><p>Essential</p></td></tr><tr><td rowspan="6"><p>19</p></td><td colspan="2"><p> Malicious Code Certification:</p></td><td><p>&nbsp;</p></td></tr><tr><td colspan="2"><p>The bidder should upload following certificate in the bid: -</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>(a)This is to certify that the Hardware and the Software being offered, as part of the contract, does not contain Embedded Malicious code that would activate procedures to: -</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>(i) Inhibit the desires and designed function of the equipment.</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>(ii) Cause physical damage to the user or equipment during the exploitation.</p></td><td><p>Essential</p></td></tr><tr><td colspan="2"><p>(b) The seller will be considered to be in breach of the procurement contract, in case physical damage, loss of information or infringements related to copyright and Intellectual Property Right (IPRs) are caused due to activation of any such malicious code in embedded software.</p></td><td><p>Essential</p></td></tr><tr><td><p>20</p></td><td colspan="2"><p>Upload Manufacturer authorization: Wherever Authorised Distributors are submitting the bid, Manufacturers Authorisation Form (MAF)/Certificate with OEM details such as name, designation, address, e-mail Id and Phone No. required to be furnished along with the bid.</p></td><td><p>Essential</p></td></tr><tr><td><p>21</p></td><td colspan="2"><p>Security Feature: TPM 2.0 (Discrete) and Integrated Diagnostic Tool in BIOS.</p></td><td><p>Essential</p></td></tr><tr><td><p>22</p></td><td colspan="2"><p>All the supplied items should be from same OEM and should be compatible to each other.</p></td><td><p>Essential</p></td></tr><tr><td><p>23</p></td><td colspan="2"><p>Data Sheet of the product offered (including wireless OEM''s mouse) in the bid, are to be uploaded along with the bid documents. User can match and verify the Data Sheet with the product specification offered. In case of any unexplained mismatch of technical parameters, the bid is liable for rejection.</p></td><td><p>Essential</p></td></tr><tr><td><p>24</p></td><td colspan="2"><p>Availability of Service Centres: Bidder/OEM must have a Functional Service Centre in the State of each Consignee''s Location in case of carry-in warranty. If service centre is not already there at the time of bidding, successful bidder / OEM shall have to establish one within 30 days of award of contract. Payment shall be released only after submission of documentary evidence of having Functional Service Centre.</p></td><td><p>Essential</p></td></tr><tr><td><p>25</p></td><td colspan="2"><p>Dedicated /toll Free Telephone No. for Service Support: Bidder/OEM must have Dedicated/toll Free Telephone No. for Service Support.</p></td><td><p>Essential</p></td></tr><tr><td><p>26</p></td><td colspan="2"><p>Escalation Matrix for Service Support: Bidder/OEM must provide Escalation Matrix of Telephone Numbers for Service Support.</p></td><td><p>Essential</p></td></tr><tr><td><p>27</p></td><td colspan="2"><p>Warranty :- OEM Warranty certificate must be submitted by  Successful Bidder at the time of delivery of Goods.</p></td><td><p>Essential</p></td></tr><tr><td><p>28</p></td><td colspan="2"><p>Onsite support :-  During warranty period any breakdown, complaint, issues etc should be attended within a day, from the time of reporting at helpdesk &amp; has to be resolved within two working days.</p></td><td><p>Essential</p></td></tr><tr><td colspan="4"><p>NOTE: Please note that the above terms have to be duly tick marked at the  Bidders Compliance (YES/NO) column to confirm your compliance and  the same has to be submitted along with your valuable quote.</p></td></tr></tbody></table>', 'D:\Admin_Sharing\Laptop Procurement\20laptop.docx', false, 1);
INSERT INTO public.document_pages VALUES (23, 22, '2026-07-03', 1, 'Imported Page 1', '<table><tbody><tr><td><p><strong>Sr. No</strong></p></td><td><p><strong>Pending Issues</strong></p></td><td><p><strong>PDC</strong></p></td><td><p><strong>Current Status</strong></p></td></tr><tr><td><p>1</p></td><td><p>Systemic changes in the department: issues related Tulip system raised by PCDA (Army) Pune “Tracing the activity of allot and re-allot of 3<sup>rd</sup> party bills.”</p></td><td><p>30.05.25</p></td><td><p>In development</p><p>stage</p></td></tr><tr><td><p>2</p></td><td><p>Provide query to extract data from Tulip database for “Analysis of data of last one year through Tulip with regard to time taken to release payments by units after obtaining Cash Assignments in respect of PCDA New Delhi, CDA (Army) Delhi Cantt, PCDA (Army) Chandigarh, vis-à-vis payments by the concerned PCsDA/CsDA” An Standard format on Tulip is to be developed for future reports.”</p></td><td><p>-</p></td><td><p>Details of time-taken to release payments by units after obtaining cash assignments is not available in Tulip  </p></td></tr><tr><td><p>3</p></td><td><p>Information with respect to vendor invoice no. and date are also to be shared with vendors through Tulip.</p></td><td><p>-</p></td><td><p>Pending at HQ office - IT Wing</p></td></tr><tr><td><p>4</p></td><td><p>Status of project Tulip 2.0</p></td><td><p>-</p></td><td><p>Status Already sent</p></td></tr><tr><td><p>5</p></td><td><p>Entry of vendor details, viz., Type of industry (MSME / PSU / others etc.) in Tulip may be made compulsory.</p></td><td><p>-</p></td><td><p>Completed</p></td></tr><tr><td><p>6</p></td><td><p>Institutionalizing of internal audit mechanism for CCS programme executed under ADA.</p></td><td><p>-</p></td><td><p>-</p></td></tr><tr><td><p>7</p></td><td><p>Additional integration for sharing sanction &amp; supply order document after contract placement on GeM.</p></td><td><p>Will assess and get back</p></td><td><p>Once HQ office shares the API format in which data/documents are shared,  after consultation with GeM, the same can be implemented in tulip</p></td></tr><tr><td><p>8</p></td><td><p>Accounting modalities likely to be followed for Unified Pension Scheme(UPS) and draft amendment to Pamphlet of RDR Heads(2020 RPT</p></td><td><p>15.05.25</p></td><td><p>Provision has already been made available in Tulip/Tulip-PMS &amp; Falcon. Support is provided to skylark team too</p></td></tr><tr><td><p>9</p></td><td><p>API Integration: NIDHI 2.0</p></td><td></td><td><p>UAT is underway</p></td></tr><tr><td><p>10</p></td><td><p>OTP for biometric based login</p></td><td rowspan="4"><p>30 working days i.e. 24.06.25</p></td><td rowspan="4"><p>In Development stage</p></td></tr><tr><td><p>11</p></td><td><p>Screen logout after an appropriate time</p></td></tr><tr><td><p>12</p></td><td><p>Online auditing system for transactions in Dolphin</p></td></tr><tr><td><p>13</p></td><td><p>Maintaining audit trails which can establish digital footprints of user login, access duration of each functionary.</p></td></tr><tr><td><p>14</p></td><td><p>Identification of expenditure in r/o all the allowances under Def. Service Estimates. (emailed on 24.03.2025 &amp; 03.04.2025)</p></td><td></td><td><p>Comments were sent to HQ  through email to (‘<a href="mailto:hqitncs.dad@hub.nic.in">hqitncs.dad@hub.nic.in</a>’) on 22.05.2025</p></td></tr></tbody></table>', 'D:\Admin_Sharing\Tulip\ITSDC Pending issues (1).docx', false, 1);
INSERT INTO public.document_pages VALUES (24, 23, '2026-07-03', 1, 'Imported Page 1', '<table><tbody><tr><td><p><strong>Email dated</strong></p></td><td><p><strong>Pending Issues</strong></p></td><td><p><strong>Comments of IT&amp;SDC</strong></p></td><td><p><strong>PDC</strong></p></td></tr><tr><td><p>02.05.2025</p></td><td><p>Systematic changes in the department: Issues related to the Tulip system raised by PCDA (Army), Pune.</p></td><td></td><td></td></tr><tr><td><p>02.05.2025</p></td><td><p>SQL for Tulip Data – Refer SoM dated: 30.04.2025</p><p>"Provide a query to extract data from the Tulip database for the analysis of data from the last one year with regard to the time taken by units to release payments after obtaining Cash Assignments, in respect of PCDA New Delhi, CDA (Army) Delhi Cantt, and PCDA (Army) Chandigarh, vis-à-vis payments made by the concerned PCsDA/CsDA. A standard format on Tulip is to be developed for future reports."</p></td><td></td><td></td></tr><tr><td><p>02.05.2025</p></td><td><p>Information with respect to vendor invoice number and date is also to be shared with vendors through Tulip.</p></td><td></td><td></td></tr><tr><td><p>02.05.2025</p></td><td><p>Status of Project Tulip 2.0</p></td><td></td><td></td></tr><tr><td><p>02.05.2025 </p></td><td><p>Entry of vendor details, viz., type of industry (MSME/PSU/Others, etc.), in Tulip may be made compulsory.</p></td><td></td><td></td></tr><tr><td><p>15.04.2025</p></td><td><p>Institutionalizing an internal audit mechanism for the CCS programme executed under ADA; SOP forwarded.</p></td><td></td><td></td></tr><tr><td><p>04.04.2025</p></td><td><p>Additional integration for sharing sanction and supply order documents after contract placement on GeM.</p></td><td></td><td></td></tr><tr><td><p>03.04.2025</p></td><td><p>Accounting modalities likely to be followed for the Unified Pension Scheme (UPS) and draft amendment to the pamphlet of RDR Heads (2020 RPT).</p></td><td></td><td></td></tr><tr><td><p>28.03.2025</p></td><td><p>API integration: NIDHI 2.0</p></td><td></td><td></td></tr></tbody></table>', 'D:\Admin_Sharing\Tulip\Pending Issues.docx', false, 1);
