INSERT INTO public.document_pages VALUES (26, 25, '2026-07-03', 1, 'Imported Page 1', '<p>7.0 TECHNOLOGY STACK All ITSDC projects are built using a robust open-source stack comprising:  React JS, Spring Boot, Java, Apache, and PostgreSQL with Linux OS</p><p> This ensures scalability, interoperability, and long-term sustainability for departmental applications.</p><p>DOLPHIN replaces legacy COBOL-based systems with a modern digital platform for PBOR pay management. </p><p>It caters real time receipt, audit, processing of DO II  &amp; payment at the end of the month, AFPP fund management and final settlements with built-in automation and Appendix J compliance of approximately 13Lakh Army personnel (JCO/ORs)</p><p>	Managing over ₹1,25,000 crore Annually</p><p>	Pay fixation of last 3 pay commissions (5<sup>th</sup>,6th &amp; 7<sup>th</sup>) is handeled in Dolphin. Vintage of data is from 1998.</p><p>	Operating within a secure, closed DAD WAN network, DOLPHIN enhances accuracy, reduces rejections, and ensures audit-readiness through MIS dashboards and structured approval work-flows.</p><p>8.2 PHOENIX (Agniveer Pay System)</p><p>	PHOENIX is an enterprise-grade pay system for Agniveers under the Agnipath scheme, currently deployed at CAPAO Delhi Cantt. </p><p>	Managing over ₹ 28000 Cr annually for 1.5 lakh personnel, it ensures 99.8% accuracy and full policy compliance. </p><p>	The platform integrates modern frameworks (Java 17, Spring Boot 3.3, React JS) and PostgreSQL, reducing DO II processing time from 05 days to 1 day. </p><p>	Previous Huno system had licensing cost of nearly 10 Crores per year.</p><p><strong>8.3 FALCON (Officer Pay System)</strong></p><p>	 FALCON handles pay and entitlements for approximately 60,000 officers, amounting to ₹16000 crore annually. </p><p>	It automates real time DO II processing, complex pay fixation, arrears, and deductions in alignment with 7th CPC norms, ensuring transparency and compliance. </p><p>	The system integrates with DTS and NCS for seamless reconciliation, strengthening data integrity and governance.</p><p>	</p><p><strong>8.4 TULIP &amp; TULIP 2.0</strong></p><p><strong>	</strong>Tulip is a office automation system that caters to reginoal and functional controllers<br>	This includes</p><p>		TPP</p><p>		UP</p><p>		MRO adjustment</p><p>		Budget monitoring</p><p>		Civilian Pay system</p><p>		DAD Pay bill</p><p>	Payments worth ₹ 5Lakh Cr was paid through Tulip in the year 2024-25 </p><p><strong>	</strong>The upgraded TULIP 2.0 adds workflow tracking, dashboards, and integration with SIFA and NCS for real-time monitoring. </p><p>	It has significantly improved payment timelines, accountability, and audit transparency at regional offices.</p><p>	</p><p>10.0 CYBER SECURITY INITIATIVES</p><p>1. Conduct of voluntary cybersecurity lectures and awareness programs.</p><p>2. Continuous dark web monitoring and threat intelligence gathering</p><p>3. vulnerability analysis.</p><p>4. Real-time Security Operations Centre (SOC) monitoring</p><p>5. Recent data leaks identified</p><p>	a. Malicious Dolphin Circular (Screenshots in slide)</p><p>	b. Malicious phishing Domains mimicking NIC mail Login (Screenshots in slide)</p><p>	c. CGDA website leak analysis (Screenshots in slide)</p><p>	d. Flagged ‘purported’ Kavach App breach.<br></p>', 'D:\Admin_Sharing\Addl CG visit\Comp Analysis edit doc.odt', false, 1);
INSERT INTO public.document_pages VALUES (27, 26, '2026-07-03', 1, 'Imported Page 1', '<p><strong>AI-Enabled Transformation of Defence Payments &amp; Pension Administration</strong></p><p>(Speech Note for CGDA)</p><p>Respected CGDA Sir,</p><p>	India’s Defence Financial ecosystem today operates through robust, specialised digital platforms:</p><p>		●​ Falcon – Officers’ Pay &amp; Allowances​</p><p>		●​ Dolphin – Soldiers’ Pay​</p><p>		●​ Phoenix – Agniveer Pay Processing​</p><p>		●​ SPARSH – Pension Administration​</p><p>		●​ Tulip 2.0 – Centralised Third-Party Payments​</p><p>	These platforms have successfully digitised Defence financial operations.</p><p>	The next strategic step is not new systems — it is intelligent integration through Artificial Intelligence.</p><p>_________________________________________________________________________________________</p><p><strong>From Digitisation to Intelligence</strong></p><p>	We have achieved large-scale digitisation.</p><p>	The transformation ahead is to make the system intelligent, predictive, and preventive.</p><p>	AI will not replace officers or existing controls.</p><p>	AI will function as an Efficient Financial Agent — strengthening scrutiny, accelerating validation, and	supporting decision-making.</p><p>_________________________________________________________________________________________</p><p><strong>1. From Processing to Intelligent Validation</strong></p><p>	Across Falcon, Dolphin and Phoenix:</p><p>		●​ AI can automatically cross-verify entitlements, rank data, allowances, arrears, and</p><p>		service records.​</p><p>		●​ Detect abnormal patterns before payment release.​</p><p>		●​ Flag only high-risk cases for focused human review.​</p><p>	Outcome: Faster processing with stronger safeguards.</p><p><strong>2. From Pension Disbursement to Pension Assurance</strong></p><p>	Through SPARSH:</p><p>		●​ AI can continuously validate pension calculations.​</p><p>		●​ Assess the impact of DA revisions or policy changes instantly.​</p><p>		●​ Monitor disbursements for inconsistencies.​</p><p>	Outcome: Reduced errors, faster revisions, improved pensioner confidence.</p><p><strong>3. From Audit to Preventive Financial Vigilance</strong></p><p>	Across Tulip 2.0 and core payment systems:</p><p>		●​ Continuous AI-based scanning of ECS and third-party payments.​</p><p>		●​ Pattern recognition for anomalies or duplication.​</p><p>		●​ Evidence-backed alerts with transaction details.​</p><p>	Outcome: Shift from post-facto audit to real-time preventive vigilance.</p><p><strong>4. From Grievance Handling to Intelligent Resolution</strong></p><p>	Using AI-assisted grievance tools:</p><p>		●​ Understand petitions in natural language.​</p><p>		●​ Identify root cause directly from structured databases.​</p><p>		●​ Suggest corrective action with data-backed explanation.​</p><p>	Outcome: Faster disposal, reduced escalation, improved morale.</p><p><strong>Leveraging India’s Sovereign AI Stack</strong></p><p>	This transformation aligns with India’s national AI vision and Atma-nirbhar goals:</p><p>		1.​ Model Layer – Domain-trained financial AI models​</p><p>		2.​ Compute Layer – Secure GPU-based processing​</p><p>		3.​ Infrastructure Layer – On-premise Defence deployment​</p><p>		4.​ Data Centre Layer – Structured financial databases​</p><p>		5.​ Application Layer – Validation, anomaly detection, dashboards​</p><p>	This ensures sovereign control, security, and scalability.</p><p>_________________________________________________________________________________________</p><p><strong>Strategic Impact for CGDA Organisation</strong></p><p>	●​ End-to-end intelligent automation across pay and pension lifecycle.​</p><p>	●​ Reduction in manual workload with better focus on complex cases.​</p><p>	●​ Preventive fraud detection and financial discipline.​</p><p>	●​ Data-driven forecasting and policy support.​</p><p>	●​ Strengthened credibility of Defence Accounts.​</p><p>_________________________________________________________________________________________</p><p><strong>Closing Statement</strong></p><p>Artificial Intelligence will elevate Defence Payments &amp; Pension administration from a digital processing framework to an intelligent financial governance system.</p><p>It will enhance speed, accuracy, transparency, and financial integrity — while reinforcing the CGDA organisation’s role as the guardian of Defence financial discipline.</p><p>Thank you, Sir.</p>', 'D:\Admin_Sharing\AI in DAD.odt', false, 1);
