INSERT INTO public.document_pages VALUES (30, 29, '2026-07-03', 1, 'Imported Page 1', '<p><strong>To</strong></p><p><strong>The CDA (IT&amp;SDC)</strong></p><p><strong>Secunderabad</strong></p><p><strong>TECHNICAL BID EVALUATION COMMITTEE REPORT</strong></p><p><strong>Sub:</strong> Report of the Technical Bid Evaluation Committee – Reg.</p><p>	The Technical Bid Evaluation Committee constituted for evaluation of the technical bids in respect of the subject procurement met to examine the technical bids received against the Bid Document, including the Bid Corrigendum and Buyer''s Additional Terms &amp; Conditions (ATC).</p><p>	A total of <strong>08 (Eight)</strong> technical bids were received within the stipulated time. During the course of evaluation, it was observed that certain bidders had not furnished all the requisite documents as prescribed in the bid. Accordingly, the Committee sought the missing documents from the concerned bidders.</p><p>	In response, only <strong>04 (Four)</strong> bidders submitted the requisite documents within the prescribed time. The Committee examined all the technical bids, including the additional documents submitted, with reference to the eligibility criteria, technical specifications, and other conditions stipulated in the Bid Document, Bid Corrigendum, and Buyer''s ATC.</p><p>	Based on the detailed scrutiny, it was found that only <strong>02 (Two)</strong> bidders have complied with all the terms and conditions of the bid and are, therefore, <strong>technically qualified</strong>.</p><p>	The remaining <strong>06 (Six)</strong> bidders have not fulfilled the mandatory requirements of the Bid Document and, in accordance with the directions of the Competent Authority, are <strong>not technically qualified</strong>. Accordingly, their technical bids are recommended for rejection.</p><p>	The Committee, therefore, recommends that only the technically qualified bidders may be considered for opening of the Financial Bid.</p><p>This report is submitted for record and further necessary action.</p><p><strong>N Ramachandran, SAO			T Vanaja, SAO		K Naveen Kumar, AAO</strong></p>', 'D:\Admin_Sharing\CBILLS\CHT\Technical Committee Report.odt', false, 1);
