INSERT INTO public.document_pages VALUES (33, 32, '2026-07-03', 1, 'Imported Page 1', '<p><strong>UNDERTAKING</strong></p><p>I, K M Siva Shankar, IDAS, JCDA, Office of the CDA (IT&amp;SDC) Secunderabad, do hereby solemnly affirm and state as follows:</p><ol><li>That the telephone/Internet connection is installed at my residence and is being used for official as well as personal purposes.</li><li>That my spouse, K Sugirtha, IRAS, who is employed in Southern Railways, Chennai, has not claimed any reimbursement for the said telephone connection or any other residential telephone bill from her office.</li><li>That I am, therefore, eligible to claim reimbursement of the telephone bills as per the admissible rules.</li></ol><p>I hereby declare that the information furnished above is true to the best of my knowledge and belief. In case any of the statements are found to be false, I shall be liable for disciplinary action as per rules.</p><p><strong>Date:</strong> __________<br><strong>Place:</strong> __________</p><p><strong>Signature:</strong> __________________<br>K M Siva Shankar, IDAS</p>', 'D:\Admin_Sharing\CBILLS\Personal Telephone Bills\Undertaking.odt', false, 1);
INSERT INTO public.document_pages VALUES (34, 33, '2026-07-03', 1, 'Imported Page 1', '<p>From</p><p>T Rambabu, IDAS</p><p>Controller</p><p>O/o CDA (IT&amp;SDC)</p><p>Secunderabad</p><p>To</p><p>The CGDA,</p><p>O/o The CGDA</p><p>Ulan Batar Road</p><p>Palam, New Delhi - 10</p><p>Sub: REQUEST FOR GRANT OF CASUAL LEAVE</p><p>Respected Madam,</p><p>	I may please be sanctioned 02 days CL from 20.01.2025 to 21.01.2025 as I have to attend to personal matters.</p><p>	Thanking you,</p><p>										</p><p>Date: 17.01.2025</p><p>											T Rambabu</p><p>											(Controller)</p><p>										         Ph: 9490173505</p><p>		</p>', 'D:\Admin_Sharing\CDA Sect\CDA Leave.odt', false, 1);
INSERT INTO public.document_pages VALUES (35, 34, '2026-07-03', 1, 'Imported Page 1', '<p>From</p><p>T Rambabu, IDAS</p><p>Controller</p><p>CDA (IT&amp;SDC)</p><p>Secunderabad</p><p>To</p><p>The CGDA</p><p>(AN-I Sn)</p><p>Ulan Batar Road</p><p>Palam, Delhi Cantt – 10</p><p>	Sub: Request for Medical Leave – Reg.</p><p>Respected Madam,</p><p>	I have been suffering with severe toothache for the past week, so I visited the Military Dental Centre this morning for treatment. The doctor performed a tooth extraction and recommended 7 days of rest.</p><p>	Therefore it is requested to grant 07days medical leave </p><p>Thanking you,</p><p>											yours sincerely		</p><p>Place:	Secunderabad										</p><p>Date:	27.01.2025									  (T Rambabu)</p><p>										                Controller</p>', 'D:\Admin_Sharing\CDA Sect\Medical LEave.odt', false, 1);
INSERT INTO public.document_pages VALUES (36, 35, '2026-07-03', 1, 'Imported Page 1', '<p>Annexure</p><p>Details of the Nominee (s): </p><p>(a) Name of the individual (s) responsible (Dr./Mr./Ms.)</p><p>	1. Shri. K M Siva Shankar, IDAS, JCDA, O/o The CDA (IT&amp;SDC)</p><p>	2. Partha Ghosh, SAO, O/o The CDA (IT&amp;SDC)</p><p>	3. Shri Amber Murtuza Ansari, AAO. O/o The CDA (IT&amp;SDC)</p><p>	4. Shri A Deepak, AAO, O/o The CDA (IT&amp;SDC)</p><p>	5. Shri Piyush Handa, AAO, O/o The CDA (IT&amp;SDC)</p><p>	6. Shri B Vijay Kumar, Sr. Aud, O/o The CDA (IT&amp;SDC)</p><p>	7. Shri K Vikram, Sr. Aud, O/o The CDA (IT&amp;SDC)</p><p>(b) Name of the office:</p><p>	O/o The CDA (IT&amp;SDC) Secunderabad</p><p>(c) Complete Postal Address (with pin code):</p><p>	O/o The CDA (IT&amp;SDC)</p><p>	PAO (ORs) AOC Compound</p><p>	Mornington Road,</p><p>	Tirumalagiri, Secunderabad</p><p>	Telangana – 500 015</p><p>(d) Contact details:</p>', 'D:\Admin_Sharing\CGHS_KVN.odt', false, 1);
