INSERT INTO public.document_pages VALUES (38, 37, '2026-07-03', 1, 'Imported Page 1', '', 'D:\Admin_Sharing\Correspondence_    IT\Dolphin__Issues\Dolphin_Issues_since_15122023.odt', false, 1);
INSERT INTO public.document_pages VALUES (39, 38, '2026-07-03', 1, 'Imported Page 1', '<p><strong>Annexure – B</strong></p><p><strong>Changes in Tulip 2.0</strong></p><table><thead><tr><th><p><strong>S.No</strong></p></th><th><p><strong>Functionalities in Tulip 2.0</strong></p></th><th><p><strong>Current Status</strong></p></th></tr></thead><tbody><tr><td><p>1</p></td><td><p>Technology Stack Upgrade</p></td><td><p>Tulip has been upgraded from Seam 2.2 to a modern, industry-standard stack using <strong>React JS and Spring Boot</strong>, delivering improved performance, scalability, and maintainability.</p></td></tr><tr><td><p>2</p></td><td><p>Hosting process and Tulip architecture: </p></td><td><p>Hosting will be done in <strong>centralized</strong> way.<br>[3 models were discussed (Decentralized, Hybrid, Centralized)].</p></td></tr><tr><td><p>3</p></td><td><p>Centralized Master Data Management</p></td><td><p>Earlier, offices maintained separate local tables for Units, Vendors, and Bank details. These have now been unified into <strong>Central Unit, Vendor, and Bank Masters</strong>, providing a single authoritative data source and ensuring seamless integration, consistency, and easier maintenance across all offices.</p></td></tr><tr><td><p>4</p></td><td><p>Role-Based Authentication</p></td><td><p>Existing activity-based authentication required mapping each user to individual activities. Tulip 2.0 replaces this with a streamlined <strong>role-based</strong> authentication system, simplifying user management and improving access control, security, and scalability.</p></td></tr><tr><td><p>5</p></td><td><p>Implementation of 14 digit unique unit code for all departmental applications.</p></td><td><p>A <strong>14-digit FIS code</strong>, already used in the existing Tulip system, has now been integrated into Tulip 2.0 also.</p></td></tr><tr><td><p>6</p></td><td><p>Redesigning R Section role; data capture at dak diarisation (bill intake).</p></td><td><p>Tulip 2.0 adds <strong>QR-based bill capture</strong> and <strong>encrypted JSON bulk diarisation</strong>, along with support for receiving bills in XML format to eliminate manual diarisation and enhance end-to-end connectivity. It is also ready to return passed-bill details in<strong> XML format</strong>.</p></td></tr><tr><td><p>7</p></td><td><p>Merging Store/M/GeM/third-party bills and audit section change proposal.</p></td><td><p>As approved by <strong>CGDA (MoM dated 25.07.2024)</strong>, Stores &amp; Misc sections have been reorganized into Third-party Payment Section and Unit Payment Section. All imprest and public fund payments will be processed through the Unit Payment Section, while GeM bills will be handled by the Third-party Payment Section.</p></td></tr><tr><td><p>8</p></td><td><p>Enhanced Randomization </p></td><td><p>In Tulip 2.0, bill <strong>randomisation</strong> now uses SecureRandom from java.security within Spring Boot, providing stronger randomness and enhanced security. GO Level</p></td></tr><tr><td><p>9</p></td><td><p>Enhanced Logging Mechanism</p></td><td><p>In Tulip 2.0, application errors are auto-logged into date-wise log files, enabling easier monitoring and troubleshooting.</p></td></tr><tr><td><p>10</p></td><td><p>Back Navigation Control</p></td><td><p>In Tulip 2.0, the browser back button is disabled to prevent data resubmission and navigation errors, ensuring smoother workflow and better security.</p></td></tr><tr><td><p>11</p></td><td><p>Favourites Module Feature</p></td><td><p>In Tulip 2.0, users can mark commonly used modules as Favourites, which appear on the left panel after login for quicker, easier access.</p></td></tr><tr><td><p>12</p></td><td><p>Analytical Dashboard</p></td><td><p>Tulip 2.0 includes a comprehensive dashboard that delivers analytical insights on budget and expenditure, enabling better monitoring and informed decision-making.</p></td></tr><tr><td><p>13</p></td><td><p>Pending Tasks Panel</p></td><td><p>In Tulip 2.0, pending tasks appear on the right side of the landing page after login, helping users quickly view and prioritize their actions.</p></td></tr><tr><td><p>14</p></td><td><p>Data Loss Prevention Alert</p></td><td><p>In Tulip 2.0, users receive a confirmation alert when refreshing, preventing accidental data loss and ensuring safer data handling.</p></td></tr><tr><td><p>15</p></td><td><p>Global Exception Handling</p></td><td><p>In Tulip 2.0, a global exception handler captures all exceptions—caught or uncaught—and displays clear, user-friendly messages instead of raw JBoss errors or stack traces, greatly improving user experience and system professionalism.</p></td></tr><tr><td><p>16</p></td><td><p>Medical Section – new features</p></td><td><p>The system auto-computes CGHS - based disallowances using standardized rates, supports section-wise cost calculations with manual entry options, and allows procedure updates through approved, time-stamped work flows. It generates a comprehensive disallowance report and offers a simple, user-friendly interface for faster, minimal-effort processing.</p></td></tr><tr><td><p>17</p></td><td><p>Revamp of Civilian Pay section</p></td><td><p>The Civilian Pay section has been revamped with automation features similar to Tulip PMS, eliminating manual pay entry, unlinked demand recoveries, and the need for the Consolidated PM-CS.</p></td></tr><tr><td><p>18</p></td><td><p>Roll Back </p></td><td><p>Before DP Sheet generation only.</p></td></tr><tr><td><p>19</p></td><td><p>ECHS</p></td><td></td></tr><tr><td></td><td></td><td><p>Uniform Budget Checking across all modules like Bills, Medical, Transport.</p></td></tr><tr><td></td><td></td><td><p>An alert on clicking refresh, to confirm if it is intended action or accidental thus preventing losing data already entered.</p></td></tr><tr><td><p>20</p></td><td><p>Creation of Vigilance &amp; Test Audit modules.</p></td><td><p>Planned for future implementation</p></td></tr><tr><td><p>21</p></td><td><p>LAO Module</p></td><td><p>Planned for future implementation</p></td></tr></tbody></table><p>Sd/-</p><p>JCDA</p><p>ITSDC</p><p><strong>Annexure – C</strong></p><p><strong>Integration of Office Automation Projects (OAPs)</strong></p><table><thead><tr><th><p><strong>Sl.</strong></p></th><th><p><strong>OAP Module</strong></p></th><th><p><strong>Current Status</strong></p></th><th><p><strong>PDC</strong></p></th></tr></thead><tbody><tr><td><p>1</p></td><td><p>Regional Controller Modules</p></td><td><p>As on date, Core Tulip (Regional Controller Modules) has been developed by IT&amp;SDC and ready to roll out</p></td><td><p>NA</p></td></tr><tr><td rowspan="3"><p>2</p></td><td><p>Functional Controller</p><p>Modules</p></td><td><p>Implemented in existing Tulip.</p></td><td><p>NA</p></td></tr><tr><td><p>Navy &amp; Air force</p></td><td><p>Imprest Modules to be included in Tulip 2.0</p></td><td><p>01.04.2026</p></td></tr><tr><td><p>IDS</p></td><td><p>Payment Authority Module to be included in Tulip 2.0</p></td><td><p>01.04.2026</p></td></tr><tr><td><p>3</p></td><td><p>HAL </p></td><td><p>Inputs awaited from HAL Bengaluru</p></td><td><p>-</p></td></tr><tr><td rowspan="2"><p>4</p></td><td rowspan="2"><p>Foreign Payments Module</p></td><td><p>Development Work is in progress and will be included in existing Tulip</p></td><td><p>01.01.2026</p></td></tr><tr><td><p>Roll out in Tulip 2.0 is planned</p></td><td><p>01.04.2026</p></td></tr><tr><td><p>5</p></td><td><p>Nodal Payments Module</p></td><td><p>Study of existing PHP programme is on-going.</p></td><td><p>01.04.2026</p></td></tr><tr><td><p>6</p></td><td><p>Fund Module</p></td><td><p>Taken care in Nidhi.</p></td><td><p>NA</p></td></tr></tbody></table>', 'D:\Admin_Sharing\Correspondence_    IT\TULIP_2.0\Annex - B & C - Tulip 2.0.odt', false, 1);
INSERT INTO public.document_pages VALUES (40, 39, '2026-07-03', 1, 'Imported Page 1', '<p>To</p><p>The CDA</p><p>Admin Pay Sn</p><p>CDA Secunderabad</p><p><strong>Subject:</strong> Application for Grant of House Rent Allowance (HRA)</p><p>Respected Sir,</p><p>	I, Dhruv Bhardwaj, AAO (Employee ID: 98347760), presently posted in the O/o CDA (IT &amp; SDC), Secunderabad, respectfully submit that I have been transferred from PCDA(O) Pune to IT&amp;SDC Secunderabad and reported for duty on 09 March 2026.</p><p>Due to the transfer, I am currently residing in rented accommodation at Flay No. 101 Block A tulip Greenfield apartments narne estate Kondapur, as no government accommodation has been allotted to me so far. In view of the same, I request that House Rent Allowance (HRA) may kindly be granted to me w.e.f 01.03.2026, I will be very thankful to you.</p><p>Thanking You.</p><p>Yours faithfully,          </p><p><br>Dhruv Bhardwaj        <br>AAO (98347760)       <br>O/o CDA (IT &amp; SDC) <br>Secunderabad          </p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\Dhruv HRA.odt', false, 1);
INSERT INTO public.document_pages VALUES (41, 40, '2024-09-05', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p><strong>OFFICE GUIDELINES FOR OFFICIAL LAPTOP DISTRIBUTION</strong></p><p>	</p><p>In order to ensure proper usage, maintenance, and security of the official laptops being distributed, the following guidelines must be strictly adhered to by all officials receiving a laptop:</p><p>1. <strong>Responsibility for Laptop Maintenance and Damage.</strong></p><ul><li>The assigned official is fully responsible for the proper upkeep and safe handling of the laptop.</li><li>Any physical damage, hardware failure due to mishandling, or loss of the laptop will be borne by the concerned official.</li><li>Officials must report any technical issues immediately to the Admin for timely resolution.</li></ul><p>2. <strong>Data Security and Confidentiality</strong></p><ul><li>The official must ensure that all data stored on the laptop is kept confidential and is used strictly for official purposes.</li><li>Storing or sharing sensitive office data with unauthorized personnel is strictly prohibited.</li><li>Any data leak or unauthorized access due to negligence will be the responsibility of the assigned official.</li></ul><p>3. <strong>Cybersecurity and Safe Usage</strong></p><ul><li>Officials must adhere to cybersecurity best practices, as outlined in the HQ’s master circular No. MEch/IT&amp;S/810/Cyber Security dated 05.09.2024 (Available on CGDA official website) . These instructions include essential cybersecurity measures such as using strong passwords and enabling multi-factor authentication where applicable.</li><li>The laptop must not be used for downloading, installing, or running unauthorized software or applications.</li><li>Any cyber-attack, virus infection, or security breach due to negligence or unauthorized activities will be the responsibility of the concerned official.</li></ul><p>4. <strong>Official Use Only</strong></p><ul><li>The laptop is provided strictly for official purposes and must not be used for personal activities.</li><li>Transferring the laptop to another person or unauthorized third party is strictly prohibited.</li></ul><p>5. <strong>Return and Handover</strong></p><ul><li>Upon resignation, transfer, or at the request of the office, the laptop must be returned in good working condition.</li><li>All official data must be backed up and handed over before returning the laptop.</li></ul><p>I, _________ ________________________________________(Name, Desgn/Acc.No.), acknowledge receipt of the official laptop bearing serial number ___________________ , wireless mouse and laptop bag. I have read, understood, and agree to abide by the above guidelines. I accept full responsibility for its security, maintenance, and appropriate usage.</p><p>Signature: ______</p><p>Date: _______</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\Laptop Distribution Norms.odt', false, 1);
INSERT INTO public.document_pages VALUES (42, 41, '2024-09-06', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Gen Corr								Dated: 06.09.2024</p><p>To</p><p>The Officer in charge</p><p>Admin-III</p><p>O/o the CDA Secunderabd</p><p>no.1 Staff road</p><p>Secunderabad - 500009</p><p><strong>Subject: Request for Replacement of Non-Functional Fluorescent Lights with LED Lights</strong></p><p>	</p><p>	It is to bring to your attention an issue concerning the lighting in the Conference Hall, Training Hall, and PC Lab of this office. The fluorescent lights installed in these locations have been malfunctioning for some time. They frequently flicker, fail to start, or provide inadequate illumination, which has significantly impacted the smooth functioning of the office.</p><p>	Given these issues, it is requested that the existing fluorescent lights be replaced with LED lights. This measure would improve reliability, energy efficiency, lifespan, and reduce maintenance requirements.</p><p>	An early action on this request is highly appreciated.</p><p>Senior Accounts Officer</p><p>(IT&amp;SDC)</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\lights replacement.odt', false, 1);
INSERT INTO public.document_pages VALUES (43, 42, '2025-06-16', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Estt/Vol-VI		       				     			     Dt: 16.06.2025</p><p>To</p><p>The Officer-in-Charge</p><p>O/o the GE (South)</p><p>MES Complex, Mudfort</p><p>Secunderabad - 09</p><p><strong>Subject: Request for Urgent Attention to Facility Issues</strong></p><p>It is brought to your kind attention that several pressing facility-related issues within our premises require urgent action to ensure a safe and functional work environment:</p><ol><li><strong>Generator Auto-On Malfunction</strong></li></ol><p>The generator fails to start automatically during power outages, affecting the smooth functioning of the office. A thorough inspection of the generator and associated components is requested to restore automatic functionality.</p><ol><li><strong>Water Leakage in Personal Assistant Room</strong></li></ol><p>Persistent leakage from the toilet on the floor above has caused dampness, foul odour, and an unhygienic environment in the PA’s room. Immediate repair and sanitization are requested.</p><ol><li><strong>Light Pole Installation at Entrance</strong></li></ol><p>Inadequate lighting at the main entrance poses safety risks, particularly during early morning and evening hours, and has coincided with increased snake sightings. The installation of a light pole is urgently needed to improve visibility and enhance overall security.</p><ol><li><strong>Parking Area Congestion</strong></li></ol><p>The existing parking area has become congested due to an increase in the office''s posted strength. It is requested that a parking shed be constructed in the vacant space adjacent to the office premises to accommodate the increased number of personnel.</p><ol><li><strong>Electrical Wiring and UPS Sockets</strong></li></ol><p>There is a need to install approximately four UPS power sockets to support essential systems. Additionally, proper electrical wiring for balanced load distribution is required to ensure safe and uninterrupted operation of equipment.</p><p>Your kind intervention to resolve the above issues at the earliest is highly appreciable. </p><p>										K M Siva Shankar, IDAS</p><p>										    (Jt.CDA – IT&amp;SDC)</p><p>Copy to :</p><p>Officer-in-Charge</p><p>Admin – III Sn		 	- For Information Please.</p><p>O/o The CDA Secunderabad							 K M Siva Shankar, IDAS</p><p>										     (Jt.CDA – IT&amp;SDC)</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\MES Issues Ltr.odt', false, 1);
INSERT INTO public.document_pages VALUES (44, 43, '2026-06-17', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Gen.Corr/2026-27	                 	  				     Dt: 17.06.2026</p><p>To</p><p>The Officer in charge</p><p>O&amp;M Section</p><p>O/o The CDA</p><p>No.1 Staff Road</p><p>Secunderabad - 09	</p><p>Sub:  TD to RTC (SR) Bengaluru for attending Workshop on Noting &amp; Drafting I– Reg.</p><p>		</p><p>	It is submitted that the Competent Authority has approved the proposal for deputing Shri Sumit Kumar Saini, Steno-II (98346016), on Temporary Duty to RTC (SR), Bengaluru for attending the Workshop on "Noting &amp; Drafting – I" scheduled from 09.07.2026 to 10.07.2026.</p><p>	In view of the above, it is requested that the above official may kindly be nominated from this office for the aforesaid workshop and confirmation of nomination may please be intimated to this office.</p><p>								Sr.Accounts Officer</p><p>(IT&amp;SDC)</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\O&M Letter.odt', false, 1);
INSERT INTO public.document_pages VALUES (45, 44, '2025-03-06', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Gen Corr								Dated: 06.03.2025</p><p>To</p><p>The GE (South)</p><p>Mudfort,Gunrock Enclave</p><p>Secunderabad - 500009</p><p><strong>Subject: Request for Construction of a Parking Lot at O/o CDA (IT&amp;SDC), Secunderabad</strong></p><p><strong>	With the increase in the posted strength of CDA (IT&amp;SDC), Secunderabad, the existing parking facility has become inadequate to accommodate the growing number of vehicles owned by officials and staff members. The current parking area is often congested, leading to inconvenience for employees and visitors alike.</strong></p><p><strong>	To address this issue and ensure a well-organized and hassle-free parking arrangement, it is requested that a new parking lot be constructed adjacent to the existing parking space. This will not only enhance the overall infrastructure of the office premises but also provide a more systematic and efficient parking facility, reducing any disruptions caused due to the lack of sufficient parking space.</strong></p><p><strong>	Considering the increasing number of personnel and vehicles, an expansion of the parking facility is essential for smooth functioning and convenience. Therefore, your kind consideration and approval of this request would be highly appreciated.</strong></p><p>Senior Accounts Officer</p><p>(IT&amp;SDC)</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\Parking_Facility.odt', false, 1);
INSERT INTO public.document_pages VALUES (46, 45, '2024-10-14', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Gen.Corr		                 	  				     Dt: 14.10.2024</p><p>To </p><p>The Officer in charge</p><p>AN-III Section</p><p>O/o CDA Secunderabad</p><p>No. 1 Staff Road</p><p>Secunderabad-09</p><p>Sub: Request for Room repair and maintenance</p><p>	This is to bring to your immediate attention to the poor condition of the room located at CDA (IT&amp;SDC), Secunderabad . The room is experiencing multiple maintenance problems that are impacting the work environment. The walls of the room exhibit significant wear and tear, with multiple patches of peeling paint and dampness. Further, there is persistent water leakage from the roof, particularly during rainy seasons, leading to further damage to the interior.</p><p>	In view of the above, It is kindly requested that necessary repairs and maintenance be done to the room at the earliest please.</p><p>Sr.Accounts Officer</p><p>(IT&amp;SDC)</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\pa_room.odt', false, 1);
INSERT INTO public.document_pages VALUES (47, 46, '2024-12-20', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Gen Corr								Dated: 20.12.2024</p><p>To</p><p>The GE (South)</p><p>Mudfort,Gunrock Enclave</p><p>Secunderabad – 500009</p><p><strong>Subject: Request for Replacement of Damaged Floor Tile</strong></p><p><strong>	I am directed to bring to your kind attention that a floor tile in the first floor of the CDA(IT&amp;SDC) Secunderabad has developed a bulge, which may pose a safety hazard and compromise the aesthetics of the premises.</strong></p><p>	It is requested that necessary action be taken to replace the damaged tile at the earliest, ensuring the floor is restored to its original condition.</p><p>	Your prompt action on this matter would be greatly appreciated</p><p>Asst. Accounts Officer</p><p>(IT&amp;SDC)</p>', 'D:\Admin_Sharing\Correspondence_ Gnrl\tile bulge.odt', false, 1);
INSERT INTO public.document_pages VALUES (48, 47, '2025-08-07', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Estt/Vol-VII							     Dated: 07.08.2025</p><p>To</p><p>The Officer-in-Charge</p><p>IT &amp; S Section</p><p>O/o The CDA</p><p>No.1 Staff Road</p><p>Secunderabad – 15</p><p>	Sub: Quarterly payment of CAMC of Computer Hardware and Peripherals-Reg.</p><p>*********</p><p>	It is certified that the services rendered by the AMC vendor, M/s Chanak Tech Services Pvt. Ltd., for the period from 03.04.2025 to 02.07.2025 have been found to be satisfactory.</p><p>										</p><p>										Sr. Accounts Officer</p><p>										 (Admin - IT &amp; SDC)</p><p>											</p>', 'D:\Admin_Sharing\Estt. Volumes\AMC - Satisfactory.odt', false, 1);
INSERT INTO public.document_pages VALUES (49, 48, '2025-01-07', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Estt/Vol-VI		       				     	Dt: 07.01.2025</p><p>To </p><p>The Officer in Charge</p><p>Admin-II Sn</p><p>O/o the CDA Secunderabad	</p><p>No. 1 Staff Road</p><p>Secunderabad-09</p><p>Sub: Annual Increment due for Jan-2025</p><p>	</p><p>&lt;&lt;&lt;&gt;&gt;&gt;</p><p>	The details of officers/staff serving in the O/o CDA (IT&amp;SDC) Secunderabad who were absent on 01.01.2025 are provided below.</p><table class="table table-bordered"><tbody><tr><td><p>S.no</p></td><td><p>Name, Grade &amp; Personal no.</p></td><td><p>Period &amp; Type of Leave/Absence</p></td><td><p>Date of Reporting for Duty</p></td><td><p>Remarks</p></td></tr><tr><td><p>1</p></td><td><p>V Naga Prasad, SAO/98335515</p></td><td><p>07.12.24 to 03.01.25</p></td><td><p>06.01.25</p></td><td></td></tr><tr><td><p>2</p></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>	</p><p>						</p><p>										 Sr. Accounts Officer</p><p>									  	   (Admin -IT&amp;SDC)    </p>', 'D:\Admin_Sharing\Estt. Volumes\Gnrl\Annual_increment.odt', false, 1);
