INSERT INTO public.document_pages VALUES (51, 50, '2025-08-12', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Estt./Vol – VII						    Dated: 12.08.2025</p><p><strong>CIRCULAR</strong></p><p>To</p><p>All The Officers &amp; Staff</p><p>O/o The CDA (IT&amp;SDC)</p><p>Secunderabad – 15</p><p>Subject: Celebrations 	of 79<sup>th</sup> Independence Day – 15<sup>th</sup> August, 2025.</p><p>*******</p><p>	The Competent Authority has directed that the 79th Independence Day be celebrated with grandeur, gaiety, fervour, and enthusiasm on 15th August 2025 by organizing suitable programmes and activities to mark the occasion in a befitting manner.</p><p>	The details of the programmes/events on 15.08.2025 are as follows:</p><ul><li><ol><li>Hoisting of the National Flag at IT &amp; SDC Office at 07:30 AM</li><li>Refreshments &amp; Tea at IT &amp; SDC Office at 09:00 AM</li></ol></li></ul><p>2.	In view of the above, all Officers and Staff serving in the O/o The CDA (IT&amp;SDC), Secunderabad, are hereby directed to attend the above programme as per the scheduled timings.</p><p>3.	Attendance of all the Officers &amp; Staff is mandatory. Failure to attend the programme will invite disciplinary action.</p><p>	CDA has Seen.	</p><p><strong>  									      K M Siva Shankar, IDAS</strong></p><p><strong>										</strong>Jt.CDA - IT&amp;SDC</p>', 'D:\Admin_Sharing\Estt. Volumes\Gnrl\Independence Day Circular.odt', false, 1);
INSERT INTO public.document_pages VALUES (52, 51, '2025-08-26', 1, 'Imported Page 1', '<p><a href="mailto:itsdcsec-cda@nic.in"><img src="/storage/assets/febba3296499f0721b5b5926924095b85cd2a0e3f78a3603c9592db2b59ad0d6.jpeg"><img src="/storage/assets/c7f917f6d31469d8da2d0b242003e4fac5b53d60e3a5014507f876e52f1f4b67.x-wmf"></a></p><p><strong>  OFFICE OF THE CDA ( IT &amp; SDC) </strong></p><p><strong>     Mornington Road, PAO(ORs)AOC Compound, </strong></p><p><strong>Trimulgherry, Secunderabad – 500 015.</strong></p><p><strong>   Email: itsdcsec-cda@nic.in</strong></p><p><strong>Phone/ Fax No: 040-27742553/29805085</strong></p><p>No. IT&amp;SDC/Estt/Vol-VII		                    					     Dt: 26.08.2025</p><p>To<br>The Officer-in-Charge</p><p>O/o The PAO (ORs) AOC</p><p>Mornington Road</p><p>Secunderabad - 15</p><p><br>Subject: Request for Attachment of MTS for Closing Duty</p><p>	It is requested that a Multi-Tasking Staff (MTS) from PAO (ORs) AOC be attached to assist the closing-duty Auditor from IT&amp;SDC for performing closing duty at the Office of the CDA (IT&amp;SDC), Secunderabad. The arrangement is necessary as only one MTS is presently attached to IT&amp;SDC, who is currently detailed for opening duty of the IT&amp;SDC building.</p><p>	Early necessary action in the matter is requested.</p><p>				</p><p>									</p><p>										JCDA -  (IT&amp;SDC)</p>', 'D:\Admin_Sharing\Estt. Volumes\Gnrl\MTS Closing Attachment Letter.odt', false, 1);
