INSERT INTO public.document_pages VALUES (54, 53, '2024-07-30', 1, 'Imported Page 1', '<p>From</p><p>N V Girija</p><p>ACDA</p><p>CDA (IT&amp;SDC)</p><p>Secunderabad</p><p>To</p><p>The CDA (IT&amp;SDC)</p><p>Secunderabad</p><p>	Sub: Request for prior sanction of leave – Reg.</p><p>Respected Sir, </p><p>	</p><p>	Sir, I humbly request you to sanction one day RH on 16/08/2024 on a/c of Varalakshmi Vratham and 5 days Earned Leave from 19/08/2024 to 23/08/2024 along with station leaving permission to enable me to visit my family in Bangalore.</p><p>Thanking You Sir,</p><p>							Yours sincerely</p><p>Place: Secunderabad</p><p>Date: 30.07.2024</p><p>N V Girija, ACDA</p>', 'D:\Admin_Sharing\Estt. Volumes\Leaves\ACDA_EL_app.odt', false, 1);
INSERT INTO public.document_pages VALUES (55, 54, '2024-09-05', 1, 'Imported Page 1', '<p>From</p><p>	K.M.Siva Shankar, IDAS</p><p>	JCDA</p><p>	O/o The CDA (IT&amp;SDC)</p><p>	Secunderabad</p><p>To</p><p>	The CDA</p><p>	(Admin Sn)</p><p>	O/o The CDA Secunderabad</p><p>		</p><p>Sub: Application for obtaining “No Objection Certificate” for Visa Cum Proceeding Abroad – Reg.  </p><p>Respected Sir,</p><p>	</p><p>	It is humbly stated that my brother in law is working in London (UK). He went for his MBA</p><p>study to UK and thereafter he started to work in London for National Health Service (NHS). Now</p><p>my wife side family is planning for his marriage. It is planned to conduct engagement for him at</p><p>London on October first week sir. So my wife along with my father in law, mother in law and my</p><p>kid all five of us are planning to go to UK for the same please sir. So, I kindly request your good</p><p>self for providing No Objection Certificate for Visa and Proceeding Abroad please sir.</p><p>Thanking you,</p><p>Place: Secunderabad								yours faithfully</p><p>Date: 05/09/2024												</p><p>									</p><p>						</p><p>								           	   (K.M. Siva Shankar, IDAS)</p>', 'D:\Admin_Sharing\Estt. Volumes\Leaves\JCDA EX-India Leave_Application.pdf.odt', false, 1);
